const CardSwap = forwardRef<CardSwapHandle, CardSwapProps>(
  (
    {
      items,
      width = 460,
      height = 340,
      cardDistance = 60,
      verticalDistance = 70,
      depth = 90,
      skewAmount = 6,
      visibleCards = 4,
      delay = 4000,
