        Math.abs(spring.y - spring.ty) < 0.05 &&
        Math.abs(spring.s - 1) < 0.0005 &&
        Math.abs(spring.vx) + Math.abs(spring.vy) < 0.05 &&
        Math.abs(spring.vs) < 0.001;
