        <p className="pointer-events-none absolute inset-x-0 bottom-3 m-0 text-center text-[12px] [color:color-mix(in_srgb,var(--df-ink)_55%,transparent)]">
          {notice}
        </p>
      ) : null}
    </div>
  );
};

