};
const jerk = (t: number) => {
  const s = clamp(t, 0, 1);
  return s * s * s * (10 + s * (6 * s - 15));
};
const jerkV = (t: number) => {
  const s = clamp(t, 0, 1);
  return 30 * s * s * (1 - s) * (1 - s);
};
const jerkA = (t: number) => {
  const s = clamp(t, 0, 1);
