const JETS = `
uniform vec4 uJetA[${MAX_JETS}];
uniform vec4 uJetB[${MAX_JETS}];
uniform float uJetBend[${MAX_JETS}];
float jetWeight(vec2 p, vec4 a, vec4 b, out float along) {
