type Trigger = 'hover' | 'click';
type ClickHandler = (event: ReactMouseEvent<HTMLButtonElement> | PointerEvent) => void;

interface EngineProps {
  size: Size;
  altitude: number;
  hoverTime: number;
  jets: number;
  thrusters: boolean;
  trigger: Trigger;
  carryCursor: boolean;
  ramp: boolean;
