          '--jr-active': activeColor,
          '--jr-text': textColor,
          '--jr-active-text': activeTextColor,
          '--jr-gap': `${gap}px`,
          '--jr-radius': `${radius}px`,
          '--jr-h': `${h}px`,
          '--jr-font': `${font}px`,
          '--jr-px': `${px}px`
