  const options = useRef({
    releaseBehavior,
    crumpleAmount,
    crumpleDuration,
    releaseDuration,
    creaseStrength,
    draggable,
    dragRotation,
    dragRadius,
    returnToOrigin,
    disabled,
    onStateChange,
    onError
  });
  options.current = {
    releaseBehavior,
    crumpleAmount,
    crumpleDuration,
    releaseDuration,
    creaseStrength,
    draggable,
    dragRotation,
    dragRadius,
    returnToOrigin,
    disabled,
    onStateChange,
    onError
