    function wake() {
      if (!frame && !disposed && ready && inView && !document.hidden && !contextLost)
        frame = requestAnimationFrame(render);
    }

    function resize() {
      const rect = root!.getBoundingClientRect();
      viewportWidth = Math.max(1, rect.width);
      viewportHeight = Math.max(1, rect.height);
      scale =
        paperWidth *
        Math.min(1, Math.max(1, viewportWidth - 48) / paperWidth, Math.max(1, viewportHeight - 48) / paperHeight);
      sheet.scale.setScalar(scale);
      camera.aspect = viewportWidth / viewportHeight;
      camera.position.z = viewportHeight / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
      camera.updateProjectionMatrix();
      camera.updateMatrixWorld();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.setSize(viewportWidth, viewportHeight, false);
      const reach = Math.max(viewportWidth, viewportHeight);
      const angle = THREE.MathUtils.degToRad(finite(lightAngle, -35));
      light.position.set(Math.sin(angle) * reach, Math.cos(angle) * reach, reach * 4);
      light.shadow.camera.left = light.shadow.camera.bottom = -reach;
      light.shadow.camera.right = light.shadow.camera.top = reach;
      light.shadow.camera.near = 1;
      light.shadow.camera.far = reach * 6;
      light.shadow.camera.updateProjectionMatrix();
      floor.position.z = -scale * shortSide * 0.12;
      floor.scale.set(viewportWidth * 4, viewportHeight * 4, 1);
      root!.style.setProperty('--pc-image-width', `${scale}px`);
      root!.style.setProperty('--pc-image-height', `${scale * aspect}px`);
      if (!held) {
        const limitX = Math.max(0, (viewportWidth - scale) / 2 - 16);
        const limitY = Math.max(0, (viewportHeight - scale * aspect) / 2 - 16);
        posX.value = posX.target = clamp(posX.value, -limitX, limitX);
        posY.value = posY.target = clamp(posY.value, -limitY, limitY);
      }
      wake();
    }

    function finish(instant = false) {
      if (!held) return;
      const opts = options.current;
      held = false;
      hit!.setAttribute('aria-pressed', 'false');
      hit!.dataset.held = 'false';
      const captured = pointerId;
      pointerId = null;
      if (captured !== null && hit!.hasPointerCapture(captured)) hit!.releasePointerCapture(captured);
      if (opts.releaseBehavior === 'stay') {
        amount.target = amount.value;
        amount.velocity = 0;
      } else {
        amount.target = 0;
        memory.target =
          opts.releaseBehavior === 'creased'
            ? Math.max(memory.value, peak * clamp(finite(opts.creaseStrength, 0.18), 0, 1))
            : 0;
      }
      tiltX.target = tiltY.target = 0;
      if (opts.returnToOrigin && opts.releaseBehavior !== 'stay') {
        posX.target = posY.target = 0;
      } else {
        const bounds = geometry.boundingBox;
        const spanX = opts.releaseBehavior === 'stay' && bounds ? bounds.max.x - bounds.min.x : 1;
        const spanY = opts.releaseBehavior === 'stay' && bounds ? bounds.max.y - bounds.min.y : aspect;
        const halfWidth =
          ((Math.abs(Math.cos(baseRotation)) * spanX + Math.abs(Math.sin(baseRotation)) * spanY) * scale) / 2;
        const halfHeight =
          ((Math.abs(Math.sin(baseRotation)) * spanX + Math.abs(Math.cos(baseRotation)) * spanY) * scale) / 2;
        const limitX = Math.min(
          Math.max(0, finite(opts.dragRadius, 180)),
          Math.max(0, viewportWidth / 2 - halfWidth - 16)
        );
        const limitY = Math.min(
          Math.max(0, finite(opts.dragRadius, 180)),
          Math.max(0, viewportHeight / 2 - halfHeight - 16)
        );
        const coast = !reduceMotion && !keyboard && performance.now() - lastMove < 90 ? 0.06 : 0;
        posX.target = clamp(posX.value + speedX * coast, -limitX, limitX);
        posY.target = clamp(posY.value - speedY * coast, -limitY, limitY);
      }
      if (instant || keyboard || reduceMotion) for (const s of springs) advance(s, 0, 0, true);
      keyboard = false;
      publish(
        opts.releaseBehavior === 'stay' && amount.target > 0.001
          ? 'crumpled'
          : memory.target > 0.001
            ? 'creased'
            : 'flat'
      );
      wake();
    }

    function reset() {
      finish(true);
      for (const s of springs) s.target = s.value = s.velocity = 0;
      peak = 0;
      publish('flat');
      wake();
    }
    resetRef.current = reset;
    cancelRef.current = () => finish(true);

    function start() {
      held = true;
      peak = amount.value;
      amount.target = clamp(finite(options.current.crumpleAmount, 0.85), 0, 1);
      hit!.setAttribute('aria-pressed', 'true');
      hit!.dataset.held = 'true';
      publish('holding');
      wake();
    }

    function pointerDown(event: PointerEvent) {
      if (!ready || options.current.disabled || held || event.button !== 0 || !event.isPrimary) return;
      const rect = root!.getBoundingClientRect();
      pointerX = lastX = event.clientX - rect.left;
      pointerY = lastY = event.clientY - rect.top;
      setPointer(pointerX, pointerY);
      sheet.updateMatrixWorld(true);
      const intersection = raycaster.intersectObjects([front, back], false)[0];
      if (!intersection?.face) return;
      event.preventDefault();
      hit!.dataset.pointer = 'true';
      hit!.focus({ preventScroll: true });
      const { face } = intersection;
      gripIndices = [face.a, face.b, face.c];
      const attribute = geometry.attributes.position;
      a.fromBufferAttribute(attribute, face.a);
      b.fromBufferAttribute(attribute, face.b);
      c.fromBufferAttribute(attribute, face.c);
      THREE.Triangle.getBarycoord(sheet.worldToLocal(intersection.point.clone()), a, b, c, weights);
      keyboard = false;
      pointerId = event.pointerId;
      speedX = speedY = 0;
      lastMove = performance.now();
      hit!.setPointerCapture(event.pointerId);
      start();
    }

    function pointerMove(event: PointerEvent) {
      if (!held || event.pointerId !== pointerId || !options.current.draggable) return;
      const rect = root!.getBoundingClientRect();
      const now = performance.now();
      const x = event.clientX - rect.left,
        y = event.clientY - rect.top;
      const dt = Math.max(0.008, (now - lastMove) / 1000);
      speedX = (x - lastX) / dt;
      speedY = (y - lastY) / dt;
      lastX = x;
      lastY = y;
      lastMove = now;
      pointerX = clamp(x, 12, viewportWidth - 12);
      pointerY = clamp(y, 12, viewportHeight - 12);
      const maxTilt = reduceMotion
        ? 0
        : THREE.MathUtils.degToRad(clamp(finite(options.current.dragRotation, 10), 0, 60));
      tiltX.target = clamp(speedY / 1800, -1, 1) * maxTilt;
      tiltY.target = clamp(speedX / 1800, -1, 1) * maxTilt;
      wake();
    }

    function pointerUp(event: PointerEvent) {
      if (event.pointerId === pointerId) finish();
    }
    function pointerCancel(event: PointerEvent) {
      if (event.pointerId === pointerId) finish(true);
    }
    function cancel() {
      finish(true);
    }
    function blur() {
      hit!.dataset.pointer = 'false';
      cancel();
    }
    function keyDown(event: KeyboardEvent) {
      if (options.current.disabled || !ready) return;
      hit!.dataset.pointer = 'false';
      if (event.key === 'Escape') {
        event.preventDefault();
        reset();
        return;
      }
      if (event.key === ' ' || event.key === 'Enter') {
        event.preventDefault();
        if (event.repeat || held) return;
        keyboard = true;
        start();
        advance(amount, 0, 0, true);
        peak = Math.max(peak, amount.value);
      } else if (
        held &&
        keyboard &&
        options.current.draggable &&
        ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)
      ) {
        event.preventDefault();
        const step = event.shiftKey ? 30 : 12;
        const limit = Math.max(0, finite(options.current.dragRadius, 180));
        posX.target = clamp(
          posX.target + (event.key === 'ArrowRight' ? step : event.key === 'ArrowLeft' ? -step : 0),
          -Math.min(limit, viewportWidth / 3),
          Math.min(limit, viewportWidth / 3)
        );
        posY.target = clamp(
          posY.target + (event.key === 'ArrowUp' ? step : event.key === 'ArrowDown' ? -step : 0),
          -Math.min(limit, viewportHeight / 3),
          Math.min(limit, viewportHeight / 3)
        );
        wake();
      }
    }
    function keyUp(event: KeyboardEvent) {
      if (keyboard && (event.key === ' ' || event.key === 'Enter')) {
        event.preventDefault();
        finish(true);
      }
    }
    function visibility() {
      lastTime = 0;
      if (document.hidden) cancel();
      else wake();
    }
    function motionChange() {
      reduceMotion = media.matches;
      if (reduceMotion) tiltX.target = tiltY.target = 0;
      wake();
    }
    function loseContext(event: Event) {
      event.preventDefault();
      contextLost = true;
      cancel();
      hit!.disabled = true;
      setStatus('error');
      options.current.onError?.(new Error('The WebGL context was lost.'));
    }
    function restoreContext() {
      contextLost = false;
      if (ready) {
        setStatus('ready');
        hit!.disabled = options.current.disabled;
        wake();
      }
    }

    hit.addEventListener('pointerdown', pointerDown);
    hit.addEventListener('pointermove', pointerMove);
    hit.addEventListener('pointerup', pointerUp);
    hit.addEventListener('pointercancel', pointerCancel);
    hit.addEventListener('lostpointercapture', pointerUp);
    hit.addEventListener('keydown', keyDown);
    hit.addEventListener('keyup', keyUp);
    hit.addEventListener('blur', blur);
    window.addEventListener('blur', cancel);
    document.addEventListener('visibilitychange', visibility);
    media.addEventListener('change', motionChange);
    canvas.addEventListener('webglcontextlost', loseContext);
    canvas.addEventListener('webglcontextrestored', restoreContext);
    const observer = new ResizeObserver(resize);
    observer.observe(root);
    const intersectionObserver = new IntersectionObserver(entries => {
      inView = entries[0].isIntersecting;
      lastTime = 0;
      if (!inView) cancel();
      else wake();
    });
    intersectionObserver.observe(root);
    deform();
    resize();

    const loader = new THREE.TextureLoader();
    loader.setCrossOrigin('anonymous');
    function load(url: string): Promise<THREE.Texture> {
      return new Promise((resolve, reject) => {
        loader.load(
          url,
          texture => {
            if (disposed) {
              texture.dispose();
              resolve(texture);
              return;
            }
            textures.add(texture);
            texture.colorSpace = THREE.SRGBColorSpace;
            texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
            const image = texture.image as HTMLImageElement;
            const imageAspect = image.width / image.height;
            const targetAspect = paperWidth / paperHeight;
            let rx = 1,
              ry = 1;
            if (imageFit === 'cover') {
              if (imageAspect > targetAspect) rx = targetAspect / imageAspect;
              else ry = imageAspect / targetAspect;
            } else {
              if (imageAspect > targetAspect) ry = imageAspect / targetAspect;
              else rx = targetAspect / imageAspect;
            }
            texture.repeat.set(rx, ry);
            texture.offset.set((1 - rx) / 2, (1 - ry) / 2);
            resolve(texture);
          },
          undefined,
          () => reject(new Error(`Unable to load paper image: ${url}. Remote images must allow CORS.`))
        );
      });
    }
    if (src) {
      Promise.all([load(src), backSrc ? load(backSrc) : Promise.resolve(null)])
        .then(([frontTexture, backTexture]) => {
          if (disposed) return;
          if (backTexture) {
            backTexture.repeat.x *= -1;
            backTexture.offset.x = 1 - backTexture.offset.x;
          }
          frontMaterial.map = frontTexture;
          backMaterial.map = backTexture || frontTexture;
          depthMaterial.map = frontTexture;
          frontMaterial.needsUpdate = backMaterial.needsUpdate = depthMaterial.needsUpdate = true;
          ready = true;
          setStatus('ready');
          hit.disabled = options.current.disabled;
          wake();
        })
        .catch(error => {
          if (disposed) return;
          setStatus('error');
          options.current.onError?.(error);
        });
    } else {
      setStatus('error');
      options.current.onError?.(new Error('PaperCrumple requires an image src.'));
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      if (pointerId !== null && hit.hasPointerCapture(pointerId)) hit.releasePointerCapture(pointerId);
      resetRef.current = cancelRef.current = null;
      observer.disconnect();
      intersectionObserver.disconnect();
      hit.removeEventListener('pointerdown', pointerDown);
      hit.removeEventListener('pointermove', pointerMove);
      hit.removeEventListener('pointerup', pointerUp);
      hit.removeEventListener('pointercancel', pointerCancel);
      hit.removeEventListener('lostpointercapture', pointerUp);
      hit.removeEventListener('keydown', keyDown);
      hit.removeEventListener('keyup', keyUp);
      hit.removeEventListener('blur', blur);
      window.removeEventListener('blur', cancel);
      document.removeEventListener('visibilitychange', visibility);
      media.removeEventListener('change', motionChange);
      canvas.removeEventListener('webglcontextlost', loseContext);
      canvas.removeEventListener('webglcontextrestored', restoreContext);
      geometry.dispose();
      floorGeometry.dispose();
      frontMaterial.dispose();
      backMaterial.dispose();
      depthMaterial.dispose();
      floorMaterial.dispose();
      grain.dispose();
      textures.forEach(texture => texture.dispose());
      light.shadow.dispose();
      renderer.dispose();
    };
  }, [
    src,
    backSrc,
    width,
    height,
    imageFit,
    foldCount,
    foldSharpness,
    wrinkleDepth,
    paperColor,
    roughness,
    paperTexture,
    lightIntensity,
    lightAngle,
    shadow,
    shadowOpacity,
    rotation,
    seed,
    detail
  ]);

  useEffect(() => {
    resetRef.current?.();
  }, [resetKey]);
  useEffect(() => {
    if (disabled) cancelRef.current?.();
  }, [disabled]);

  const shadowFilter = shadow
    ? `drop-shadow(0 6px 10px rgb(0 0 0 / ${clamp(finite(shadowOpacity, 0.08), 0, 1)}))`
    : undefined;

  return (
    <div
      ref={rootRef}
      className={`relative isolate w-full overflow-hidden ${className}`}
      style={{ height: sceneHeight, ...style }}
      data-status={status}
    >
      <canvas
        ref={canvasRef}
        className="pointer-events-none absolute inset-0 block h-full w-full"
        aria-hidden="true"
        style={{ visibility: status === 'ready' ? 'visible' : 'hidden', filter: shadowFilter }}
      />
      {status !== 'ready' && (
        <img
          className="pointer-events-none absolute left-1/2 top-1/2 h-[var(--pc-image-height,72%)] w-[var(--pc-image-width,60%)] select-none"
          src={src || undefined}
          alt={alt}
          draggable={false}
          style={{
            objectFit: imageFit,
            transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
            filter: shadowFilter
          }}
        />
      )}
      <button
        ref={hitRef}
        type="button"
        className="peer absolute left-0 top-0 m-0 cursor-grab touch-none appearance-none select-none rounded-[2px] border-0 bg-transparent p-0 !shadow-none !outline-none [-webkit-tap-highlight-color:transparent] data-[held=true]:cursor-grabbing focus:!outline-none focus-visible:!outline-none disabled:cursor-default"
        disabled={disabled || status !== 'ready'}
        aria-label={`${alt}. Hold to crumple and drag. Keyboard: hold Space or Enter, arrow keys to move, Escape to reset.`}
        aria-pressed="false"
        style={{ visibility: status === 'ready' ? 'visible' : 'hidden' }}
      />
      <span
        className="pointer-events-none absolute bottom-6 left-[calc(50%-2px)] h-1 w-1 rounded-full bg-current opacity-0 peer-focus-visible:opacity-55 peer-data-[pointer=true]:!opacity-0"
        aria-hidden="true"
      />
      <span className="sr-only" role="status">
        {status === 'loading'
          ? 'Loading interactive paper.'
          : status === 'error'
            ? 'Interactive paper unavailable. Showing the original image.'
            : ''}
      </span>
    </div>
  );
};

export default PaperCrumple;

'use client';

import React, { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { HugeiconsIcon, type IconSvgElement } from '@hugeicons/react';
import { FavouriteIcon, FlashIcon, StarIcon } from '@hugeicons/core-free-icons';

export type PeekRatingShape = 'star' | 'heart' | 'bolt';

export interface PeekRatingProps {
  value?: number;
  defaultValue?: number;
  onChange?: (value: number) => void;
  onPreview?: (value: number | null) => void;
  count?: number;
  shape?: PeekRatingShape;
  icon?: ReactNode;
  labels?: string[];
  activeColor?: string;
  idleColor?: string;
  tipColor?: string;
  tipTextColor?: string;
  size?: number;
  lift?: number;
  magnify?: number;
  riseDuration?: number;
  popScale?: number;
  showTip?: boolean;
  allowClear?: boolean;
  readOnly?: boolean;
  disabled?: boolean;
  ariaLabel?: string;
  className?: string;
}

interface GestureState {
  hover: number | null;
  pressing: boolean;
  pointerId: number | null;
  settled: boolean;
  rect: DOMRect | null;
  rtl: boolean;
}

const EASE_OUT = 'cubic-bezier(0.23, 1, 0.32, 1)';
const SHAPES: Record<PeekRatingShape, IconSvgElement> = { star: StarIcon, heart: FavouriteIcon, bolt: FlashIcon };

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const reducedMotion = () =>
  typeof window !== 'undefined' && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

const PeekRating: React.FC<PeekRatingProps> = ({
  value: valueProp,
  defaultValue = 0,
  onChange,
  onPreview,
  count = 5,
  shape = 'star',
  icon,
  labels = [],
  activeColor = '#f5b400',
  idleColor = '#52525b',
  tipColor = '#27272a',
  tipTextColor = '#f5f5f5',
  size = 28,
  lift = 6,
  magnify = 1.15,
  riseDuration = 320,
  popScale = 1.3,
  showTip = true,
  allowClear = true,
  readOnly = false,
  disabled = false,
  ariaLabel = 'Rating',
  className = ''
}) => {
  const [inner, setInner] = useState(defaultValue);
  const value = clamp(valueProp ?? inner, 0, count);
  const interactive = !readOnly && !disabled;

  const rootRef = useRef<HTMLDivElement>(null);
  const rowRef = useRef<HTMLDivElement>(null);
  const tipEl = useRef<HTMLSpanElement>(null);
  const starEls = useRef<(HTMLElement | null)[]>([]);
  const liftEls = useRef<(HTMLSpanElement | null)[]>([]);
  const glyphEls = useRef<(HTMLSpanElement | null)[]>([]);
  const st = useRef<GestureState>({
    hover: null,
    pressing: false,
    pointerId: null,
    settled: false,
    rect: null,
    rtl: false
  });

  const paint = () => {
    const { hover, settled, rtl } = st.current;
    const previewing = hover !== null && !settled;
    const shown = previewing ? hover + 1 : value;
    const still = reducedMotion();

    for (let i = 0; i < count; i++) {
      const liftEl = liftEls.current[i];
      const glyphEl = glyphEls.current[i];
      if (!liftEl || !glyphEl) continue;
      const lifted = previewing && !still && i <= hover;
      liftEl.style.transform = lifted
        ? `translateY(${-lift}px) scale(${i === hover ? magnify : 1})`
        : 'translateY(0px) scale(1)';
      glyphEl.dataset.lit = String(i < shown);
    }

    const tip = tipEl.current;
    if (!tip) return;
    if (previewing && showTip) {
      const row = rowRef.current;
      const slot = row ? row.clientWidth / count : size;
      const visual = rtl ? count - 1 - hover : hover;
      const wasHidden = tip.dataset.show !== 'true';
      if (wasHidden) tip.style.transition = 'none';
      tip.textContent = labels[hover] ?? String(hover + 1);
      tip.style.transform = `translate(calc(${slot * (visual + 0.5)}px - 50%), 0)`;
      if (wasHidden) {
        void tip.offsetWidth;
        tip.style.transition = '';
      }
      tip.dataset.show = 'true';
    } else {
      tip.dataset.show = 'false';
    }
  };
  useLayoutEffect(paint);

  const setHover = (index: number | null) => {
    if (index === st.current.hover) return;
    st.current.hover = index;
    if (index !== null) st.current.settled = false;
    paint();
    onPreview?.(index === null ? null : index + 1);
  };
  const setHoverRef = useRef(setHover);
  setHoverRef.current = setHover;

  const measure = () => {
    const row = rowRef.current;
    if (!row) return;
    st.current.rect = row.getBoundingClientRect();
    st.current.rtl = getComputedStyle(row).direction === 'rtl';
  };

  const indexAt = (x: number, y: number): number | null => {
    const { rect, pressing, rtl } = st.current;
    if (!rect || !rect.width) return null;
    if (pressing && (y < rect.top - size || y > rect.bottom + size)) return null;
    const index = clamp(Math.floor(((x - rect.left) / rect.width) * count), 0, count - 1);
    return rtl ? count - 1 - index : index;
  };

  const commit = (next: number, pop = true) => {
    if (valueProp === undefined) setInner(next);
    onChange?.(next);
    st.current.settled = true;
    paint();
    const glyph = glyphEls.current[next - 1];
    if (pop && next > 0 && popScale > 1 && glyph && typeof glyph.animate === 'function' && !reducedMotion()) {
      glyph.getAnimations().forEach(animation => animation.cancel());
      glyph.animate(
        [
          { transform: 'scale(1)', easing: EASE_OUT },
          { transform: `scale(${popScale})`, offset: 0.35, easing: EASE_OUT },
          { transform: 'scale(1)' }
        ],
        { duration: 300 }
      );
    }
  };

  const handlePointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || e.pointerType !== 'mouse') return;
    rootRef.current?.removeAttribute('data-instant');
    measure();
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || e.button !== 0 || st.current.pointerId !== null) return;
    rootRef.current?.removeAttribute('data-instant');
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {}
    st.current.pointerId = e.pointerId;
    st.current.pressing = true;
    measure();
    setHover(indexAt(e.clientX, e.clientY));
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive) return;
    const { pressing, pointerId } = st.current;
    if (e.pointerType !== 'mouse' && !pressing) return;
    if (pressing && e.pointerId !== pointerId) return;
    if (!pressing && !st.current.rect) measure();
    setHover(indexAt(e.clientX, e.clientY));
  };

  const endPress = (e: React.PointerEvent<HTMLDivElement>) => {
    const { pressing, pointerId, hover } = st.current;
    if (!pressing || e.pointerId !== pointerId) return;
    st.current.pressing = false;
    st.current.pointerId = null;
    if (e.type === 'pointerup' && hover !== null) {
      const next = hover + 1;
      commit(allowClear && next === value ? 0 : next);
    }
    if (e.pointerType !== 'mouse') setHover(null);
  };

  const handlePointerLeave = () => {
    if (!st.current.pressing) setHover(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!interactive) return;
    const min = allowClear ? 0 : 1;
    let next: number;
    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        next = clamp(value + 1, min, count);
        break;
      case 'ArrowLeft':
      case 'ArrowDown':
        next = clamp(value - 1, min, count);
        break;
      case 'Home':
        next = 1;
        break;
      case 'End':
        next = count;
        break;
      case 'Backspace':
      case 'Delete':
        if (!allowClear) return;
        next = 0;
        break;
      case ' ':
      case 'Enter': {
        const index = starEls.current.indexOf(e.target as HTMLElement);
        if (index === -1) return;
        next = allowClear && index + 1 === value ? 0 : index + 1;
        break;
      }
      default:
        return;
    }
    e.preventDefault();
    rootRef.current?.setAttribute('data-instant', 'true');
    st.current.hover = null;
    commit(next, false);
    starEls.current[Math.max(next, 1) - 1]?.focus();
  };

  useEffect(() => {
    const reset = () => {
      st.current.pressing = false;
      st.current.pointerId = null;
