                ref={el => {
                  liftEls.current[i] = el;
                }}
                className="block origin-bottom [transition:transform_var(--pr-rise)_var(--pr-ease-out)] group-data-[instant=true]:[transition-duration:0ms] motion-reduce:transition-none"
              >
