  type ReactNode
} from 'react';
import { flushSync } from 'react-dom';

const FOLLOW = 30;
const SETTLE = 16;
const TUG = 2.4;
const TUG_DECAY = 0.14;
const SLIT = 6;
const OVER = 40;
const SLIVER = 2;
const STACK_K = 320;
const STACK_C = 22;
const STAGGER = 0.035;
const ENTER = 22;
const HYSTERESIS = 8;
const DEG = Math.PI / 180;

export interface ShredderItem {
  id: string | number;
}

export interface ShredderProps<T extends ShredderItem> {
