    setHeld(false);
    setArmed(false);
  };
  useEffect(
    () => () => {
      animX.current?.stop();
      animY.current?.stop();
      clearTimeout(dotTimer.current);
    },
    []
  );

  return (
    <span
      ref={rootRef}
      className={`group/root relative inline-block [width:var(--sl-size)] [height:var(--sl-size)]${className ? ` ${className}` : ''}`}
      data-armed={armed ? '' : undefined}
      data-sent={sent ? '' : undefined}
      style={
        {
          '--sl-size': `${size}px`,
          '--sl-svg': `${2 * H}px`,
          '--sl-pad': padColor,
          '--sl-icon': iconColor,
          '--sl-accent': accentColor,
