import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { gsap } from 'gsap';
import { SplitText } from 'gsap/SplitText';
import { ScrambleTextPlugin } from 'gsap/ScrambleTextPlugin';

gsap.registerPlugin(SplitText, ScrambleTextPlugin);

const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

type ScrambleEffect = 'scramble' | 'lift' | 'blur' | 'magnify';

export interface ScrambledTextProps {
  radius?: number;
  duration?: number;
  speed?: number;
  scrambleChars?: string;
  scrambleColor?: string;
  effect?: ScrambleEffect;
  strength?: number;
  trail?: number;
  clickBurst?: boolean;
  intro?: boolean;
  fontFamily?: string;
  color?: string;
  className?: string;
  style?: React.CSSProperties;
  children: React.ReactNode;
}

interface CharPoint {
  x: number;
  y: number;
  energy: number;
  dx: number;
  dy: number;
  shown: boolean;
}

interface Wave {
  x: number;
  y: number;
  age: number;
  r: number;
  fade: number;
  reach: number;
  life: number;
  hit: Uint8Array;
}

const PHYSICAL: Record<string, boolean> = { lift: true, blur: true, magnify: true };

const falloff = (distance: number, radius: number): number => {
  if (distance >= radius) return 0;
  const f = 1 - (distance / radius) ** 2;
  return f * f;
};

const ScrambledText: React.FC<ScrambledTextProps> = ({
  radius = 100,
  duration = 1.2,
  speed = 0.5,
  scrambleChars = '.:',
  scrambleColor = '',
  effect = 'scramble',
  strength = 1,
  trail = 0.6,
  clickBurst = true,
  intro = true,
  fontFamily = '',
  color = '',
  className = '',
  style = {},
  children
}: ScrambledTextProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);
  const resetRef = useRef<() => void>(() => {});
  const settings = { radius, duration, speed, scrambleChars, scrambleColor, effect, strength, trail, clickBurst };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;
  const textKey = typeof children === 'string' ? children : undefined;

  const [fontsReady, setFontsReady] = useState(
    () => typeof document === 'undefined' || !document.fonts || document.fonts.status === 'loaded'
  );

  useEffect(() => {
    if (fontsReady) return;
    let live = true;
    document.fonts.ready
      .then(() => {
        if (live) setFontsReady(true);
      })
      .catch(() => {
        if (live) setFontsReady(true);
      });
    return () => {
      live = false;
    };
  }, [fontsReady]);

  useIsomorphicLayoutEffect(() => {
    const root = rootRef.current;
    const textEl = textRef.current;
    if (!root || !textEl || !fontsReady) return;

    const split = SplitText.create(textEl, { type: 'chars', smartWrap: true, aria: 'none' });
    const chars = split.chars as HTMLElement[];
    const originals = chars.map(char => char.textContent ?? '');
    const glyphs = chars.map((char, i) => {
      const sizer = document.createElement('span');
      const glyph = document.createElement('span');
      sizer.textContent = originals[i];
      sizer.style.visibility = 'hidden';
      glyph.textContent = originals[i];
      glyph.style.cssText = 'position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:pre';
      char.replaceChildren(sizer, glyph);
      return glyph;
    });
    const points: CharPoint[] = chars.map(() => ({ x: 0, y: 0, energy: 0, dx: 0, dy: 0, shown: false }));
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const pointer = { x: 0, y: 0, sx: 0, sy: 0, inside: false };
    const waves: Wave[] = [];
    let measured = false;
    let fontPx = 16;
    let raf = 0;
    let last = 0;
    let moveFrame = 0;
    let decode: gsap.core.Timeline | null = null;
    let observer: IntersectionObserver | null = null;

    const scramble = (index: number, length: number, revealDelay = 0): gsap.TweenVars => {
      const { speed, scrambleChars, scrambleColor } = settingsRef.current;
      const glyph = glyphs[index];
      return {
        overwrite: true,
        duration: length,
        ease: 'none',
        scrambleText: { text: originals[index], chars: scrambleChars, speed, revealDelay },
        onUpdate: () => {
          glyph.style.color = scrambleColor && glyph.textContent !== originals[index] ? scrambleColor : '';
        }
      };
    };

    if (intro && !reduce) {
      const introLength = settingsRef.current.duration;
      const timeline = gsap.timeline({ paused: true });
      glyphs.forEach((glyph, index) => {
        const reveal = 0.15 + introLength * (0.75 * (index / glyphs.length) + 0.25 * Math.random());
        timeline.to(glyph, scramble(index, reveal + 0.1, reveal), 0);
      });
      timeline.time(0.001);
      const io = new IntersectionObserver(
        ([entry]) => {
          if (!entry.isIntersecting) return;
          io.disconnect();
          timeline.play();
        },
        { rootMargin: '0px 0px -10% 0px' }
      );
      io.observe(root);
      decode = timeline;
      observer = io;
    }

    const offsetOf = (el: HTMLElement): [number, number] => {
      let x = 0;
      let y = 0;
      for (let node: HTMLElement | null = el; node; node = node.offsetParent as HTMLElement | null) {
        x += node.offsetLeft;
        y += node.offsetTop;
      }
      return [x, y];
    };

    const measure = () => {
      fontPx = parseFloat(window.getComputedStyle(textEl).fontSize) || 16;
      const [rootX, rootY] = offsetOf(root);
      chars.forEach((char, i) => {
        const [x, y] = offsetOf(char);
        points[i].x = x - rootX + char.offsetWidth / 2;
        points[i].y = y - rootY + char.offsetHeight / 2;
      });
      measured = true;
    };

    const toLocal = (e: PointerEvent): [number, number] => {
      const rect = root.getBoundingClientRect();
      const scaleX = root.offsetWidth ? rect.width / root.offsetWidth : 1;
      const scaleY = root.offsetHeight ? rect.height / root.offsetHeight : 1;
      return [(e.clientX - rect.left) / (scaleX || 1), (e.clientY - rect.top) / (scaleY || 1)];
    };

    const clear = (i: number) => {
      const char = chars[i];
      char.style.transform = '';
      char.style.filter = '';
      char.style.opacity = '';
      char.style.zIndex = '';
      points[i].shown = false;
    };

    const paint = (i: number, mode: string, amount: number) => {
      const p = points[i];
      const e = p.energy;
      if (e < 0.001) {
        if (p.shown) clear(i);
        return;
      }
      const char = chars[i];
      p.shown = true;
      if (mode === 'lift') {
        char.style.transform = `translate3d(0, ${(-e * fontPx * 0.75 * amount).toFixed(2)}px, 0)`;
      } else if (mode === 'blur') {
        char.style.filter = `blur(${(e * fontPx * 0.24 * amount).toFixed(2)}px)`;
        char.style.opacity = (1 - e * Math.min(0.7, 0.45 * amount)).toFixed(3);
        char.style.transform = `scale(${(1 + e * 0.15 * amount).toFixed(4)})`;
      } else {
        char.style.transform = `translate3d(${p.dx.toFixed(2)}px, ${p.dy.toFixed(2)}px, 0) scale(${(1 + e * 0.85 * amount).toFixed(4)})`;
        char.style.zIndex = `${Math.round(e * 10)}`;
      }
    };

    const tick = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      if (!measured) measure();
      const s = settingsRef.current;
      const mode = PHYSICAL[s.effect] && !reduce ? s.effect : '';
      const amount = Math.max(0, s.strength);
      const reach = Math.max(1, s.radius);
      const width = Math.max(fontPx * 1.3, 16);
      const swell = mode === 'magnify' ? 0.55 : 1;
      const follow = 1 - Math.exp(-dt / 0.06);
      const attack = 1 - Math.exp(-dt / 0.08);
      const release = 1 - Math.exp(-dt / Math.max(0.04, s.trail / 3));
      pointer.sx += (pointer.x - pointer.sx) * follow;
      pointer.sy += (pointer.y - pointer.sy) * follow;

      for (const wave of waves) {
        wave.age += dt;
        const t = Math.min(1, wave.age / wave.life);
        wave.r = wave.reach * (1 - (1 - t) * (1 - t));
        wave.fade = t < 0.75 ? 1 : 1 - ((t - 0.75) / 0.25) ** 2;
      }

      let busy = waves.length > 0 || Math.abs(pointer.x - pointer.sx) + Math.abs(pointer.y - pointer.sy) > 0.2;
      for (let i = 0; i < chars.length; i += 1) {
        const p = points[i];
        let target = 0;
        let tx = 0;
        let ty = 0;
        if (mode && pointer.inside) {
          const ax = p.x - pointer.sx;
          const ay = p.y - pointer.sy;
          target = falloff(Math.hypot(ax, ay), reach);
          tx = ax * 0.5 * amount * target;
          ty = ay * 0.5 * amount * target;
        }
        for (const wave of waves) {
          const ax = p.x - wave.x;
          const ay = p.y - wave.y;
          const d = Math.hypot(ax, ay);
          const strengthAt = 1 - (0.6 * d) / wave.reach;
          if (!wave.hit[i] && d <= wave.r) {
            wave.hit[i] = 1;
            gsap.to(glyphs[i], scramble(i, Math.max(0.2, s.duration * (0.2 + 0.5 * strengthAt))));
          }
          if (mode) {
            const band = swell * strengthAt * wave.fade * Math.exp(-(((d - wave.r) / width) ** 2));
            if (band > target) {
              const push = (fontPx * 0.6 * amount * band) / (d || 1);
              target = band;
              tx = ax * push;
              ty = ay * push;
            }
          }
        }
        const k = target > p.energy ? attack : release;
        p.energy += (target - p.energy) * k;
        if (Math.abs(target - p.energy) > 0.0005) busy = true;
        if (mode === 'magnify') {
          p.dx += (tx - p.dx) * k;
          p.dy += (ty - p.dy) * k;
        }
        if (!mode) {
          if (p.shown) clear(i);
          continue;
        }
        paint(i, mode, amount);
      }

      for (let j = waves.length - 1; j >= 0; j -= 1) {
        if (waves[j].age >= waves[j].life) waves.splice(j, 1);
      }

      if (busy) raf = requestAnimationFrame(tick);
      else last = 0;
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(tick);
    };

    const scrambleNearPointer = () => {
      moveFrame = 0;
      if (!measured) measure();
      const { radius, duration } = settingsRef.current;
      glyphs.forEach((glyph, index) => {
        const p = points[index];
        const dist = Math.hypot(pointer.x - p.x, pointer.y - p.y);
        if (dist < radius) gsap.to(glyph, scramble(index, duration * (1 - dist / radius)));
      });
    };

    const handleEnter = () => {
      measured = false;
    };

    const handleMove = (e: PointerEvent) => {
      const [x, y] = toLocal(e);
      pointer.x = x;
      pointer.y = y;
      if (!pointer.inside) {
        pointer.sx = x;
        pointer.sy = y;
        pointer.inside = true;
      }
      if (PHYSICAL[settingsRef.current.effect]) {
        if (!reduce) wake();
      } else if (!moveFrame) moveFrame = requestAnimationFrame(scrambleNearPointer);
    };

    const handleLeave = () => {
      pointer.inside = false;
      wake();
    };

    const handleDown = (e: PointerEvent) => {
      if (!settingsRef.current.clickBurst || (e.pointerType === 'mouse' && e.button !== 0)) return;
      if (!measured) measure();
      const [x, y] = toLocal(e);
      let reach = 0;
      for (const p of points) reach = Math.max(reach, Math.hypot(p.x - x, p.y - y));
      reach += fontPx;
      if (waves.length > 3) waves.shift();
      waves.push({ x, y, age: 0, r: 0, fade: 1, reach, life: 0.45 + reach / 1100, hit: new Uint8Array(chars.length) });
      wake();
    };

    resetRef.current = () => {
      points.forEach(p => {
        p.energy = 0;
        p.dx = 0;
        p.dy = 0;
      });
      chars.forEach((_, i) => clear(i));
    };

    const resize = new ResizeObserver(() => {
      measured = false;
    });
    resize.observe(root);
    document.fonts?.ready
      .then(() => {
        measured = false;
      })
      .catch(() => {});

    root.addEventListener('pointerenter', handleEnter);
    root.addEventListener('pointermove', handleMove);
    root.addEventListener('pointerleave', handleLeave);
    root.addEventListener('pointerdown', handleDown);

    return () => {
      root.removeEventListener('pointerenter', handleEnter);
      root.removeEventListener('pointermove', handleMove);
      root.removeEventListener('pointerleave', handleLeave);
      root.removeEventListener('pointerdown', handleDown);
      resize.disconnect();
      cancelAnimationFrame(raf);
      cancelAnimationFrame(moveFrame);
      observer?.disconnect();
      decode?.kill();
      gsap.killTweensOf(glyphs);
      resetRef.current = () => {};
      split.revert();
    };
  }, [intro, textKey, fontsReady]);

  useEffect(() => {
    resetRef.current();
  }, [effect]);

  return (
    <div
      ref={rootRef}
      className={`m-[7vw] max-w-[800px] font-mono text-[clamp(14px,4vw,32px)] ${className}`}
      style={{ ...style, ...(color ? { color } : null), ...(fontFamily ? { fontFamily } : null) }}
    >
      <span className="sr-only">{children}</span>
      <p key={textKey} ref={textRef} aria-hidden="true">
        {children}
      </p>
    </div>
  );
};

export default ScrambledText;

'use client';

import React, {
  Children,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type RefObject
} from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

type ScrollFloatEffect = 'float' | 'flip' | 'scatter' | 'blur' | 'wave';
type ScrollFloatSplit = 'chars' | 'words';
type ScrollFloatDirection = 'up' | 'down';
type ScrollFloatOrder = 'start' | 'end' | 'center' | 'edges' | 'random';

interface ScrollFloatProps {
  children: ReactNode;
  scrollContainerRef?: RefObject<HTMLElement | null>;
  containerClassName?: string;
  textClassName?: string;
  effect?: ScrollFloatEffect;
  splitBy?: ScrollFloatSplit;
  direction?: ScrollFloatDirection;
  order?: ScrollFloatOrder;
  fromColor?: string;
  animationDuration?: number;
  ease?: string;
  scrollStart?: string;
  scrollEnd?: string;
  stagger?: number;
  distance?: number;
  stretch?: number;
  smoothing?: number;
}

const clampToScroll = (position: string) =>
  typeof position === 'string' && !position.startsWith('clamp(') ? `clamp(${position})` : position;

const clamp01 = (value: number) => Math.min(Math.max(value, 0), 1);

const smoothstep = (from: number, to: number, value: number) => {
  const k = clamp01((value - from) / (to - from));
  return k * k * (3 - 2 * k);
};

const random = (index: number, salt: number) => {
  const value = Math.sin((index + 1) * 12.9898 + salt * 78.233) * 43758.5453;
  return value - Math.floor(value);
};

const getDelays = (count: number, order: ScrollFloatOrder, stagger: number) => {
  const middle = (count - 1) / 2;
  const ranks = Array.from({ length: count }, (_, index) => {
    if (order === 'end') return count - 1 - index;
    if (order === 'center') return Math.abs(index - middle);
    if (order === 'edges') return middle - Math.abs(index - middle);
    return index;
  });
  if (order === 'random') {
    const shuffled = ranks.map((_, index) => index).sort((a, b) => random(a, 9) - random(b, 9));
    shuffled.forEach((target, rank) => {
      ranks[target] = rank;
    });
  }
  const first = Math.min(...ranks);
  return ranks.map(rank => (rank - first) * Math.max(0, stagger));
};

const ScrollFloat: React.FC<ScrollFloatProps> = ({
  children,
  scrollContainerRef,
  containerClassName = '',
  textClassName = '',
  effect = 'float',
  splitBy = 'chars',
  direction = 'up',
  order = 'start',
  fromColor = 'currentColor',
  animationDuration = 1,
  ease = 'back.inOut(2)',
  scrollStart = 'center bottom+=50%',
  scrollEnd = 'bottom bottom-=40%',
  stagger = 0.03,
  distance = 120,
  stretch = 2.3,
  smoothing = 0
}) => {
  const containerRef = useRef<HTMLHeadingElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);

  const text = useMemo(() => {
    const parts = Children.toArray(children);
    return parts.every(part => typeof part === 'string' || typeof part === 'number') ? parts.join('') : null;
  }, [children]);

  const shiftColor = fromColor && fromColor !== 'currentColor' ? fromColor : null;
  const shiftStyle = useMemo<CSSProperties | undefined>(
    () =>
      shiftColor
        ? { color: `color-mix(in oklab, ${shiftColor} calc(var(--scroll-float-mix, 0) * 100%), currentColor)` }
        : undefined,
    [shiftColor]
  );

  const splitText = useMemo(() => {
    if (text === null) return null;
    return text.split(/(\s+)/).map((word, wordIndex) =>
      word.trim() === '' ? (
        word
      ) : (
        <span className="inline-block whitespace-nowrap" data-word key={wordIndex}>
          {Array.from(word).map((char, charIndex) => (
            <span className="inline-block" data-char key={charIndex} style={shiftStyle}>
              {char}
            </span>
          ))}
        </span>
      )
    );
  }, [text, shiftStyle]);

  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  useIsomorphicLayoutEffect(() => {
    const el = containerRef.current;
    const textEl = textRef.current;
    if (!el || !textEl) return;
    if (scrollContainerRef && !scrollContainerRef.current) return;

    const scroller = scrollContainerRef?.current || window;
    const pieces = el.querySelectorAll<HTMLElement>(splitBy === 'words' ? '[data-word]' : '[data-char]');
    const targets: HTMLElement[] = pieces.length ? Array.from(pieces) : [textEl];
    const indexOf = new Map<Element, number>(targets.map((target, index) => [target, index]));
    const at = (fn: (index: number) => number) => (_: number, target: Element) => fn(indexOf.get(target) ?? 0);
    const middle = (targets.length - 1) / 2;
    const edge = (index: number) => (middle > 0 ? (index - middle) / middle : 0);
    const delays = getDelays(targets.length, order, stagger);
    const sign = direction === 'down' ? -1 : 1;
    const reach = Math.max(0, Number(distance) || 0) / 120;
    const squeeze = stretch > 0 ? stretch ** -0.43 : 1;
    const baseEase = gsap.parseEase(ease) || ((p: number) => p);
    const timing = (p: number) => clamp01(baseEase(p));
    const size = () => parseFloat(getComputedStyle(textEl).fontSize) || 16;
    const swell = (p: number) => {
      const t = timing(p);
      return 1 - Math.cos(t * Math.PI * 2.5) * Math.pow(1 - t, 2.6);
    };
    const sway = (p: number) => {
      const t = timing(p);
      return Math.sin(t * Math.PI * 2.5) * Math.pow(1 - t, 2.6);
    };
    const mm = gsap.matchMedia();

    mm.add('(prefers-reduced-motion: no-preference)', () => {
      const timeline = gsap.timeline({
        scrollTrigger: {
          trigger: el,
          scroller,
          start: scrollStart,
          end: clampToScroll(scrollEnd),
          scrub: smoothing > 0 ? smoothing : true,
          invalidateOnRefresh: true
        }
      });
      const add = (fromVars: gsap.TweenVars, toVars: gsap.TweenVars) => {
        gsap.set(targets, { willChange: 'opacity, transform', ...fromVars });
        return timeline.fromTo(
          targets,
          { willChange: 'opacity, transform', ...fromVars },
          { duration: animationDuration, stagger: (index: number) => delays[index] || 0, ...toVars },
          0
        );
      };

      if (effect === 'flip') {
        add(
          {
            rotationX: -90 * sign,
            transformPerspective: () => size() * 4,
            transformOrigin: () => `50% 50% ${(-size() * 0.55 * reach).toFixed(2)}`,
            backfaceVisibility: 'hidden'
          },
          { ease, rotationX: 0 }
        );
        add({ opacity: 0 }, { ease: (p: number) => smoothstep(0.05, 0.55, timing(p)), opacity: 1 });
      } else if (effect === 'scatter') {
        add(
          {
            x: at(index => ((random(index, 1) * 2 - 1) * 1.3 - edge(index) * 0.9) * size() * reach),
            y: at(index => sign * (0.35 + random(index, 2)) * size() * 1.1 * reach),
            rotation: at(index => (random(index, 3) < 0.5 ? -1 : 1) * (40 + random(index, 4) * 120)),
            scale: at(index => 0.35 + random(index, 5) * 0.9),
            transformOrigin: '50% 50%'
          },
          { ease, x: 0, y: 0, rotation: 0, scale: 1 }
        );
        add({ opacity: 0 }, { ease: (p: number) => smoothstep(0, 0.4, timing(p)), opacity: 1 });
      } else if (effect === 'blur') {
        add(
          {
            willChange: 'opacity, transform, filter',
            opacity: 0,
            y: () => sign * size() * 0.3 * reach,
            scale: 1.45,
            filter: () => `blur(${(size() * 0.2).toFixed(2)}px)`,
            transformOrigin: '50% 50%'
          },
          { ease, opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }
        );
      } else if (effect === 'wave') {
        add(
          {
            yPercent: 120 * reach * sign,
            scaleY: stretch,
            scaleX: squeeze,
            transformOrigin: sign > 0 ? '50% 100%' : '50% 0%'
          },
          { ease: swell, yPercent: 0, scaleY: 1, scaleX: 1 }
        );
        add({ rotation: 0 }, { ease: sway, rotation: -16 * sign });
        add({ opacity: 0 }, { ease: (p: number) => clamp01(timing(p) * 2.5), opacity: 1 });
      } else {
        add(
          {
            opacity: 0,
            yPercent: 120 * reach * sign,
            scaleY: stretch,
            scaleX: squeeze,
            transformOrigin: sign > 0 ? '50% 0%' : '50% 100%'
          },
          { ease, opacity: 1, yPercent: 0, scaleY: 1, scaleX: 1 }
        );
      }

      if (shiftColor) {
        add(
          { '--scroll-float-mix': 1 },
          { ease: (p: number) => smoothstep(0.5, 1, timing(p)), '--scroll-float-mix': 0 }
        );
      }
    });

    return () => mm.revert();
  }, [
    mounted,
    scrollContainerRef,
    text,
    effect,
    splitBy,
    direction,
    order,
    shiftColor,
    animationDuration,
    ease,
    scrollStart,
    scrollEnd,
    stagger,
    distance,
    stretch,
    smoothing
  ]);

  return (
    <h2
      ref={containerRef}
      className={`my-5 ${effect === 'float' ? 'overflow-hidden' : 'overflow-x-clip overflow-y-visible'} ${containerClassName}`}
    >
      {text !== null && <span className="sr-only">{text}</span>}
      <span
        ref={textRef}
        className={`inline-block text-[clamp(1.6rem,8vw,10rem)] font-black text-center leading-[1.5] ${textClassName}`}
        style={text === null ? shiftStyle : undefined}
        aria-hidden={text !== null ? true : undefined}
      >
        {splitText ?? children}
      </span>
    </h2>
  );
};

export default ScrollFloat;

'use client';

import React, {
  Children,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject
} from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

const SCRUB_SPAN = 0.5;
const RISE_MASK = 'inset(-1em -1em -0.15em -1em)';

type RevealSplit = 'words' | 'chars' | 'lines';
type RevealEffect = 'fade' | 'rise' | 'flip' | 'scale';
type RevealMode = 'scrub' | 'enter';

interface ScrollRevealProps {
  children: ReactNode;
  scrollContainerRef?: RefObject<HTMLElement | null>;
  enableBlur?: boolean;
  baseOpacity?: number;
  baseRotation?: number;
  blurStrength?: number;
  baseOffset?: number;
  stagger?: number;
  smoothing?: number;
  splitBy?: RevealSplit;
  effect?: RevealEffect;
  mode?: RevealMode;
  duration?: number;
  highlightColor?: string;
  containerClassName?: string;
  textClassName?: string;
  rotationEnd?: string;
  wordAnimationEnd?: string;
}

interface RevealLook {
  effect: RevealEffect;
  masked: boolean;
  baseOpacity: number;
  blur: number;
  offset: number;
  highlightColor: string;
}

const clampToScroll = (position: string) =>
  typeof position === 'string' && !position.startsWith('clamp(') ? `clamp(${position})` : position;

const clamp01 = (value: number) => Math.min(Math.max(value, 0), 1);
const smooth = (value: number) => value * value * (3 - 2 * value);
const easeOut = (value: number) => 1 - Math.pow(1 - value, 3);
const easeBack = (value: number, overshoot: number) => {
  const shifted = value - 1;
  return 1 + (overshoot + 1) * shifted * shifted * shifted + overshoot * shifted * shifted;
};
const glowAt = (t: number) => (t <= 0 || t >= 1 ? 0 : t < 0.35 ? smooth(t / 0.35) : 1 - smooth((t - 0.35) / 0.65));

const paintPiece = (piece: HTMLElement, t: number, look: RevealLook) => {
  let reveal = t;
  let fadeIn = t;
  let motion = '';
  if (look.effect === 'rise') {
    reveal = easeOut(t);
    fadeIn = clamp01(reveal * 1.25);
    if (reveal < 1) {
      motion = look.masked
        ? `translateY(${((1 - reveal) * 100).toFixed(2)}%) translateY(${((1 - reveal) * 0.2).toFixed(3)}em)`
        : `translateY(${((1 - reveal) * 0.8).toFixed(3)}em)`;
    }
  } else if (look.effect === 'flip') {
    reveal = easeBack(t, 1.2);
    fadeIn = clamp01(t * 2);
    if (t < 1) motion = `perspective(6em) rotateX(${((1 - reveal) * 90).toFixed(2)}deg)`;
  } else if (look.effect === 'scale') {
    reveal = easeBack(t, 1.6);
    fadeIn = clamp01(t * 1.6);
    if (t < 1) motion = `scale(${(0.35 + 0.65 * reveal).toFixed(4)})`;
  }
  if (look.highlightColor) fadeIn = Math.max(fadeIn, clamp01(t / 0.35));
  const settle = clamp01(reveal);
  const lift = look.offset * (1 - settle);
  piece.style.opacity = t >= 1 ? '' : (look.baseOpacity + (1 - look.baseOpacity) * fadeIn).toFixed(3);
  piece.style.transform = [lift ? `translateY(${lift.toFixed(2)}px)` : '', motion].filter(Boolean).join(' ');
  piece.style.filter = look.blur && settle < 1 ? `blur(${(look.blur * (1 - settle)).toFixed(2)}px)` : '';
  if (look.highlightColor) {
    const glow = glowAt(t);
    piece.style.color =
      glow > 0.002 ? `color-mix(in srgb, ${look.highlightColor} ${(glow * 100).toFixed(1)}%, currentColor)` : '';
  }
};

const ScrollReveal: React.FC<ScrollRevealProps> = ({
  children,
  scrollContainerRef,
  enableBlur = true,
  baseOpacity = 0.1,
  baseRotation = 3,
  blurStrength = 4,
  baseOffset = 0,
  stagger = 0.05,
  smoothing = 0,
  splitBy = 'words',
  effect = 'fade',
  mode = 'scrub',
  duration = 0.8,
  highlightColor = '',
  containerClassName = '',
  textClassName = '',
  rotationEnd = 'bottom bottom',
  wordAnimationEnd = 'bottom bottom'
}) => {
  const containerRef = useRef<HTMLHeadingElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);

  const text = useMemo(() => {
    const parts = Children.toArray(children);
    return parts.every(part => typeof part === 'string' || typeof part === 'number') ? parts.join('') : null;
  }, [children]);

  const splitText = useMemo(() => {
    if (text === null) return null;
    return text.split(/(\s+)/).map((word, index) =>
      word.trim() === '' ? (
        word
      ) : (
        <span className="inline-block" data-word key={index}>
          {splitBy === 'chars' ? (
            Array.from(word).map((char, charIndex) => (
              <span className="inline-block" data-piece key={charIndex}>
                {char}
              </span>
            ))
          ) : (
            <span className="inline-block" data-piece>
              {word}
            </span>
          )}
        </span>
      )
    );
  }, [text, splitBy]);

  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  useIsomorphicLayoutEffect(() => {
    const el = containerRef.current;
    const textEl = textRef.current;
    if (!el || !textEl) return;
    if (scrollContainerRef && !scrollContainerRef.current) return;

    const scroller = scrollContainerRef?.current || window;
    const wrappers = Array.from(el.querySelectorAll<HTMLElement>('[data-word]'));
    const pieces = wrappers.length ? Array.from(el.querySelectorAll<HTMLElement>('[data-piece]')) : [textEl];
    const viewportHeight = () => (scroller instanceof HTMLElement ? scroller.clientHeight : window.innerHeight);
    const scrub = smoothing > 0 ? smoothing : true;
    const span = mode === 'enter' ? Math.max(0.05, duration) : SCRUB_SPAN;
    const gap = Math.max(0, stagger);
    const look: RevealLook = {
      effect,
      masked: effect === 'rise' && wrappers.length > 0,
      baseOpacity,
      blur: enableBlur ? blurStrength : 0,
      offset: baseOffset,
      highlightColor
    };
    const mm = gsap.matchMedia();

    mm.add('(prefers-reduced-motion: no-preference)', () => {
      const order = pieces.map((_, index) => index);
      const last = pieces.map(() => -1);
      const state = { p: 0 };
      let count = pieces.length;

      const measure = () => {
        if (splitBy !== 'lines' || !wrappers.length) return;
        let line = -1;
        let top = -Infinity;
        wrappers.forEach((wrapper, index) => {
          const next = wrapper.offsetTop;
          if (Math.abs(next - top) > 2) {
            line += 1;
            top = next;
          }
          order[index] = line;
        });
        count = line + 1;
      };

      const total = () => span + Math.max(0, count - 1) * gap;

      const render = () => {
        const at = state.p * total();
        pieces.forEach((piece, index) => {
          const t = clamp01((at - order[index] * gap) / span);
          if (t === last[index]) return;
          last[index] = t;
          paintPiece(piece, t, look);
        });
      };

      measure();
      pieces.forEach(piece => {
        piece.style.willChange =
          pieces.length > 80 ? '' : effect === 'fade' && !baseOffset ? 'opacity' : 'opacity, transform';
        piece.style.transformOrigin = effect === 'flip' ? '50% 100%' : '';
      });
      if (look.masked) {
        wrappers.forEach(wrapper => {
          wrapper.style.clipPath = RISE_MASK;
        });
      }
      render();

      if (mode === 'enter') {
        let played = false;
        const play = () => {
          if (played) return;
          played = true;
          gsap.to(state, { p: 1, duration: total(), ease: 'none', onUpdate: render });
          if (baseRotation) gsap.to(el, { rotate: 0, duration: Math.min(total(), 1.4), ease: 'power3.out' });
        };
        const startAt = () => {
          const view = viewportHeight();
          const top =
            el.getBoundingClientRect().top -
            (scroller instanceof HTMLElement
              ? scroller.getBoundingClientRect().top + scroller.clientTop - scroller.scrollTop
              : -window.scrollY);
          const raw = top - view + 0.2 * Math.min(el.offsetHeight, view);
          return Math.min(raw, ScrollTrigger.maxScroll(scroller) - 1);
        };
        if (baseRotation) gsap.set(el, { transformOrigin: '0% 50%', rotate: baseRotation });
        ScrollTrigger.create({
          trigger: el,
          scroller,
          start: startAt,
          onEnter: play,
          onLeave: play,
          onRefresh: (self: ScrollTrigger) => {
            if (self.progress > 0) play();
          }
        });
      } else {
        if (baseRotation) {
          gsap.fromTo(
            el,
            { transformOrigin: '0% 50%', rotate: baseRotation },
            {
              ease: 'none',
              rotate: 0,
              scrollTrigger: {
                trigger: el,
                scroller,
                start: 'top bottom',
                end: clampToScroll(rotationEnd),
                scrub
              }
            }
          );
        }
        gsap.to(state, {
          p: 1,
          ease: 'none',
          onUpdate: render,
          scrollTrigger: {
            trigger: el,
            scroller,
            start: () => `top bottom-=${0.2 * Math.min(el.offsetHeight, viewportHeight())}`,
            end: clampToScroll(wordAnimationEnd),
            scrub
          }
        });
      }

      const resizeObserver =
        splitBy === 'lines' && typeof ResizeObserver !== 'undefined'
          ? new ResizeObserver(() => {
              measure();
              last.fill(-1);
              render();
            })
          : null;
      resizeObserver?.observe(textEl);

      return () => {
        resizeObserver?.disconnect();
        pieces.forEach(piece => {
          piece.style.opacity = '';
          piece.style.transform = '';
          piece.style.transformOrigin = '';
          piece.style.filter = '';
          piece.style.color = '';
          piece.style.willChange = '';
        });
        wrappers.forEach(wrapper => {
          wrapper.style.clipPath = '';
        });
      };
    });

    return () => mm.revert();
  }, [
    mounted,
    scrollContainerRef,
    text,
    splitBy,
    effect,
    mode,
    duration,
    highlightColor,
    enableBlur,
    baseOpacity,
    baseRotation,
    blurStrength,
    baseOffset,
    stagger,
    smoothing,
    rotationEnd,
    wordAnimationEnd
  ]);

  return (
    <h2 ref={containerRef} className={`my-5 ${containerClassName}`} aria-label={text ?? undefined}>
      <span
        ref={textRef}
        className={`block text-[clamp(1.6rem,4vw,3rem)] leading-[1.5] font-semibold ${textClassName}`}
        aria-hidden={text === null ? undefined : true}
      >
        {splitText ?? children}
      </span>
    </h2>
  );
};

export default ScrollReveal;

'use client';

import React, { useLayoutEffect, useRef, useState } from 'react';
import {
  motion,
  useAnimationFrame,
  useMotionValue,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
  useVelocity
} from 'motion/react';

interface VelocityMapping {
  input: [number, number];
  output: [number, number];
}

interface VelocityTextProps {
  children: React.ReactNode;
  baseVelocity: number;
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
  className?: string;
  damping: number;
  stiffness: number;
  numCopies: number;
  velocityMapping?: VelocityMapping;
  parallaxClassName?: string;
  scrollerClassName?: string;
  parallaxStyle?: React.CSSProperties;
  scrollerStyle?: React.CSSProperties;
  separator?: React.ReactNode;
  pauseOnHover: boolean;
  hoveredRef: React.RefObject<boolean>;
  skewWithVelocity: number;
  scaleWithVelocity: number;
  outline: boolean;
  gap: number;
  fontSize?: number | string;
  fontWeight?: number | string;
  color?: string;
  draggable: boolean;
}

interface ScrollVelocityProps {
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
  texts: React.ReactNode[];
  velocity?: number;
  className?: string;
  damping?: number;
  stiffness?: number;
  numCopies?: number;
  velocityMapping?: VelocityMapping;
  parallaxClassName?: string;
  scrollerClassName?: string;
  parallaxStyle?: React.CSSProperties;
  scrollerStyle?: React.CSSProperties;
  separator?: React.ReactNode;
  pauseOnHover?: boolean;
  fadeEdges?: boolean;
  skewWithVelocity?: number;
  scaleWithVelocity?: number;
  outlineAlternate?: boolean;
  gap?: number;
  fontSize?: number | string;
  fontWeight?: number | string;
  color?: string;
  draggable?: boolean;
}

const smootherstep = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);

const FADE_STEPS = Array.from({ length: 9 }, (_, i) => i / 8);

const FADE_MASK = `linear-gradient(to right, ${[
  ...FADE_STEPS.map(t => `rgba(0, 0, 0, ${smootherstep(t).toFixed(3)}) ${(t * 12).toFixed(1)}%`),
  ...FADE_STEPS.map(t => `rgba(0, 0, 0, ${smootherstep(1 - t).toFixed(3)}) ${(88 + t * 12).toFixed(1)}%`)
].join(', ')})`;

const OUTLINE_STYLE: React.CSSProperties = {
  WebkitTextFillColor: 'transparent',
  WebkitTextStroke: 'max(1px, 0.028em) currentColor'
};

function wrap(min: number, max: number, v: number): number {
  const range = max - min;
  const mod = (((v - min) % range) + range) % range;
  return mod + min;
}

function useElementWidth<T extends HTMLElement>(ref: React.RefObject<T | null>): number {
  const [width, setWidth] = useState(0);

  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;

    if (typeof ResizeObserver === 'undefined') {
      const updateWidth = () => setWidth(element.offsetWidth);
      updateWidth();
      window.addEventListener('resize', updateWidth);
      return () => window.removeEventListener('resize', updateWidth);
    }

    const observer = new ResizeObserver(([entry]) => {
      setWidth(entry.borderBoxSize?.[0]?.inlineSize ?? entry.contentRect.width);
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref]);

  return width;
}

function VelocityText({
  children,
  baseVelocity,
  scrollContainerRef,
  className = '',
  damping,
  stiffness,
  numCopies,
  velocityMapping,
  parallaxClassName,
  scrollerClassName,
  parallaxStyle,
  scrollerStyle,
  separator,
  pauseOnHover,
  hoveredRef,
  skewWithVelocity,
  scaleWithVelocity,
  outline,
  gap,
  fontSize,
  fontWeight,
  color,
  draggable
}: VelocityTextProps) {
  const baseX = useMotionValue(0);
  const skewX = useMotionValue(0);
  const scaleY = useMotionValue(1);
  const scrollOptions = scrollContainerRef ? { container: scrollContainerRef } : {};
  const { scrollY } = useScroll(scrollOptions);
  const scrollVelocity = useVelocity(scrollY);
  const smoothVelocity = useSpring(scrollVelocity, { damping, stiffness });
  const velocityFactor = useTransform(
    smoothVelocity,
    velocityMapping?.input || [0, 1000],
    velocityMapping?.output || [0, 5],
    { clamp: false }
  );
  const reduceMotion = useReducedMotion();

  const copyRef = useRef<HTMLSpanElement>(null);
  const copyWidth = useElementWidth(copyRef);

  const x = useTransform(baseX, v => {
    if (copyWidth === 0) return '0px';
    return `${wrap(-copyWidth, 0, v)}px`;
  });

  const directionFactor = useRef<number>(1);
  const pace = useRef<number>(1);
  const fling = useRef<number>(0);
  const drag = useRef({ active: false, pointerId: -1, lastX: 0, lastTime: 0, velocity: 0, travel: 0 });

  useAnimationFrame((t, delta) => {
    if (reduceMotion) return;

    const grab = drag.current;
    const seconds = Math.min(delta, 64) / 1000;
    const targetPace = grab.active || (pauseOnHover && hoveredRef.current) ? 0 : 1;
    pace.current += (targetPace - pace.current) * (1 - Math.exp(-delta / 150));

    let moveBy = directionFactor.current * baseVelocity * (delta / 1000);

    if (velocityFactor.get() < 0) {
      directionFactor.current = -1;
    } else if (velocityFactor.get() > 0) {
      directionFactor.current = 1;
    }

    moveBy += directionFactor.current * moveBy * velocityFactor.get();
    let travel = moveBy * pace.current;

    if (!grab.active && fling.current !== 0) {
      travel += fling.current * seconds;
      fling.current *= Math.exp(-delta / 420);
      if (Math.abs(fling.current) < 4) fling.current = 0;
    }

    baseX.set(baseX.get() + travel);

    if (!skewWithVelocity && !scaleWithVelocity && skewX.get() === 0 && scaleY.get() === 1) return;

    const thrown = grab.active ? grab.velocity : fling.current;
    const scrollSurge = Math.tanh(Math.abs(smoothVelocity.get()) / 1600) * pace.current;
    const throwSurge = Math.tanh(Math.abs(thrown) / 2000);
    const surge = Math.max(scrollSurge, throwSurge);
    const heading =
      throwSurge > scrollSurge
        ? Math.sign(thrown)
        : Math.sign(travel) || directionFactor.current * Math.sign(baseVelocity);
    const ease = 1 - Math.exp(-delta / 110);
    const nextSkew = skewX.get() + (-heading * skewWithVelocity * surge - skewX.get()) * ease;
    const nextScale = scaleY.get() + (1 + scaleWithVelocity * surge - scaleY.get()) * ease;
    skewX.set(Math.abs(nextSkew) < 0.01 && !skewWithVelocity ? 0 : nextSkew);
    scaleY.set(Math.abs(nextScale - 1) < 0.0005 && !scaleWithVelocity ? 1 : nextScale);
  });

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!draggable || (event.pointerType === 'mouse' && event.button !== 0)) return;
    const grab = drag.current;
    grab.active = true;
    grab.pointerId = event.pointerId;
    grab.lastX = event.clientX;
    grab.lastTime = event.timeStamp;
    grab.velocity = 0;
    grab.travel = 0;
    fling.current = 0;
    event.currentTarget.setPointerCapture?.(event.pointerId);
    event.currentTarget.style.cursor = 'grabbing';
  };

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const grab = drag.current;
    if (!grab.active || event.pointerId !== grab.pointerId) return;
    const dx = event.clientX - grab.lastX;
    const dt = Math.max(event.timeStamp - grab.lastTime, 1);
    grab.lastX = event.clientX;
    grab.lastTime = event.timeStamp;
    grab.travel += Math.abs(dx);
    baseX.set(baseX.get() + dx);
    grab.velocity += ((dx / dt) * 1000 - grab.velocity) * (1 - Math.exp(-dt / 50));
  };

  const handlePointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    const grab = drag.current;
    if (!grab.active || event.pointerId !== grab.pointerId) return;
    grab.active = false;
    const resting = event.timeStamp - grab.lastTime > 90;
    fling.current = resting ? 0 : Math.max(-5000, Math.min(5000, grab.velocity));
    grab.velocity = 0;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    event.currentTarget.style.cursor = 'grab';
  };

  const handleClickCapture = (event: React.MouseEvent<HTMLDivElement>) => {
    if (drag.current.travel > 6) {
      event.preventDefault();
      event.stopPropagation();
    }
  };

  const spans = [];
  for (let i = 0; i < numCopies; i++) {
    spans.push(
      <span
        className={`flex-shrink-0 ${className}`}
        key={i}
        ref={i === 0 ? copyRef : null}
        aria-hidden={i > 0 ? true : undefined}
        style={!separator && gap > 0 ? { paddingRight: gap } : undefined}
      >
        {children}&nbsp;
        {separator ? (
          <>
            <span style={gap > 0 ? { margin: `0 ${gap / 2}px` } : undefined}>{separator}</span>&nbsp;
          </>
        ) : null}
      </span>
    );
  }

  const typeStyle: React.CSSProperties = {
    ...(fontSize !== undefined
      ? { fontSize: typeof fontSize === 'number' ? `${fontSize}px` : fontSize, lineHeight: 1 }
      : {}),
    ...(fontWeight !== undefined ? { fontWeight } : {}),
    ...(color ? { color } : {}),
    ...(outline ? OUTLINE_STYLE : {})
  };

  return (
    <div
      className={`${parallaxClassName} relative overflow-hidden`}
      style={{
        ...(draggable ? { cursor: 'grab', userSelect: 'none', WebkitUserSelect: 'none', touchAction: 'pan-y' } : {}),
        ...parallaxStyle
      }}
      onPointerDown={draggable ? handlePointerDown : undefined}
      onPointerMove={draggable ? handlePointerMove : undefined}
      onPointerUp={draggable ? handlePointerUp : undefined}
      onPointerCancel={draggable ? handlePointerUp : undefined}
      onClickCapture={draggable ? handleClickCapture : undefined}
    >
      <motion.div
        className={`${scrollerClassName} flex whitespace-nowrap text-center font-sans text-4xl font-bold tracking-[-0.02em] drop-shadow md:text-[5rem] md:leading-[5rem]`}
        style={{ x, skewX, scaleY, ...typeStyle, ...scrollerStyle }}
      >
        {spans}
      </motion.div>
    </div>
  );
}

export const ScrollVelocity: React.FC<ScrollVelocityProps> = ({
  scrollContainerRef,
  texts = [],
  velocity = 100,
  className = '',
  damping = 50,
  stiffness = 400,
  numCopies = 6,
  velocityMapping = { input: [0, 1000], output: [0, 5] },
  parallaxClassName = 'parallax',
  scrollerClassName = 'scroller',
  parallaxStyle,
  scrollerStyle,
  separator = '',
  pauseOnHover = false,
  fadeEdges = false,
  skewWithVelocity = 0,
  scaleWithVelocity = 0,
  outlineAlternate = false,
  gap = 0,
  fontSize,
  fontWeight,
  color,
  draggable = false
}) => {
  const hoveredRef = useRef(false);

  return (
    <section
      className="w-full"
      style={fadeEdges ? { WebkitMaskImage: FADE_MASK, maskImage: FADE_MASK } : undefined}
      onPointerEnter={() => {
        hoveredRef.current = true;
      }}
      onPointerLeave={() => {
        hoveredRef.current = false;
      }}
    >
      {texts.map((text, index) => (
        <VelocityText
          key={index}
          className={className}
          baseVelocity={index % 2 !== 0 ? -velocity : velocity}
          scrollContainerRef={scrollContainerRef}
          damping={damping}
          stiffness={stiffness}
          numCopies={numCopies}
          velocityMapping={velocityMapping}
          parallaxClassName={parallaxClassName}
          scrollerClassName={scrollerClassName}
          parallaxStyle={parallaxStyle}
          scrollerStyle={scrollerStyle}
          separator={separator}
          pauseOnHover={pauseOnHover}
          hoveredRef={hoveredRef}
          skewWithVelocity={skewWithVelocity}
          scaleWithVelocity={scaleWithVelocity}
          outline={outlineAlternate && index % 2 !== 0}
          gap={gap}
          fontSize={fontSize}
          fontWeight={fontWeight}
          color={color}
          draggable={draggable}
        >
          {text}
        </VelocityText>
      ))}
    </section>
  );
};

export default ScrollVelocity;

'use client';

import { useEffect, useRef } from 'react';
import type { CSSProperties, ReactNode } from 'react';

type Easing = 'smooth' | 'linear' | 'snappy';
type Trigger = 'loop' | 'hover' | 'view';

export interface ShinyTextProps {
  text?: string;
  children?: ReactNode;
  color?: string;
  shineColor?: string;
  speed?: number;
  delay?: number;
  angle?: number;
  shineWidth?: number;
  softness?: number;
  bands?: number;
  glow?: number;
  direction?: 'left' | 'right';
  easing?: Easing;
  trigger?: Trigger;
  yoyo?: boolean;
  followPointer?: boolean;
  pauseOnHover?: boolean;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
}

interface Settings {
  color: string;
  shineColor: string;
  speed: number;
  delay: number;
  angle: number;
  shineWidth: number;
  softness: number;
  bands: number;
  glow: number;
  sign: number;
  ease: (t: number) => number;
  trigger: Trigger;
  yoyo: boolean;
  followPointer: boolean;
  pauseOnHover: boolean;
  disabled: boolean;
}

const EASINGS: Record<Easing, (t: number) => number> = {
  linear: t => t,
  smooth: t => 0.5 - Math.cos(Math.PI * t) / 2,
  snappy: t => (t < 0.5 ? 16 * Math.pow(t, 5) : 1 - Math.pow(-2 * t + 2, 5) / 2)
};
const TRIGGERS: Trigger[] = ['loop', 'hover', 'view'];
const FALLOFF = [0, 0.2, 0.4, 0.6, 0.8, 1];

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

let paint: CanvasRenderingContext2D | null = null;

const parseColor = (value: string): number[] | null => {
  if (typeof document === 'undefined') return null;
  if (!paint) paint = document.createElement('canvas').getContext('2d');
  if (!paint) return null;
  paint.fillStyle = '#000000';
  paint.fillStyle = value;
  const resolved = String(paint.fillStyle);
  if (resolved.startsWith('#')) {
    return [1, 3, 5].map(i => parseInt(resolved.slice(i, i + 2), 16)).concat(1);
  }
  const parts = resolved.match(/[\d.]+/g);
  if (!parts || parts.length < 3) return null;
  return [Number(parts[0]), Number(parts[1]), Number(parts[2]), parts.length > 3 ? Number(parts[3]) : 1];
};

const blend = (from: number[], to: number[], amount: number) => {
  const channel = (a: number, b: number) =>
    Math.round(Math.pow(Math.pow(a / 255, 2.2) * (1 - amount) + Math.pow(b / 255, 2.2) * amount, 1 / 2.2) * 255);
  const alpha = from[3] * (1 - amount) + to[3] * amount;
  if (alpha <= 0) return 'rgba(0, 0, 0, 0)';
  const weigh = (a: number, b: number) => (a * from[3] * (1 - amount) + b * to[3] * amount) / alpha;
  const r = from[3] === to[3] ? channel(from[0], to[0]) : Math.round(weigh(from[0], to[0]));
  const g = from[3] === to[3] ? channel(from[1], to[1]) : Math.round(weigh(from[1], to[1]));
  const b = from[3] === to[3] ? channel(from[2], to[2]) : Math.round(weigh(from[2], to[2]));
  return `rgba(${r}, ${g}, ${b}, ${Math.round(alpha * 1000) / 1000})`;
};

const ShinyText = ({
  text,
  children,
  color = '#b5b5b5',
  shineColor = '#ffffff',
  speed = 2,
  delay = 0,
  angle = 120,
  shineWidth = 40,
  softness = 0.8,
  bands = 1,
  glow = 0,
  direction = 'left',
  easing = 'smooth',
  trigger = 'loop',
  yoyo = false,
  followPointer = false,
  pauseOnHover = false,
  disabled = false,
  className = '',
  style
}: ShinyTextProps) => {
  const rootRef = useRef<HTMLSpanElement>(null);
  const glowRef = useRef<HTMLSpanElement>(null);
  const settingsRef = useRef<Settings | null>(null);
  const syncRef = useRef<(() => void) | null>(null);
  const content = children ?? text;

  settingsRef.current = {
    color,
    shineColor,
    speed: Math.max(0.1, speed),
    delay: Math.max(0, delay),
    angle,
    shineWidth: clamp(shineWidth, 2, 200),
    softness: clamp(softness, 0, 1),
    bands: clamp(Math.round(bands), 1, 3),
    glow: clamp(glow, 0, 1),
    sign: direction === 'right' ? 1 : -1,
    ease: EASINGS[easing as Easing] ?? EASINGS.smooth,
    trigger: TRIGGERS.includes(trigger as Trigger) ? (trigger as Trigger) : 'loop',
    yoyo,
    followPointer,
    pauseOnHover,
    disabled
  };

  useEffect(() => {
    syncRef.current?.();
  });

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const state = {
      pos: null as number | null,
      vel: 0,
      phase: 'idle',
      from: 0,
      to: 0,
      start: 0,
      duration: 1,
      resume: 0,
      flip: false,
      inside: false,
      target: 0,
      visible: true,
      seen: false,
      colors: ''
    };
    let base: number[] | null = null;
    let shine: number[] | null = null;
    let clear: number[] | null = null;
    let raf = 0;
    let timer = 0;
    let last = 0;
    let alive = true;

    const extent = () => {
      const s = settingsRef.current!;
      return s.shineWidth / 2 + (s.bands - 1) * s.shineWidth * 1.3 + 2;
    };
    const entry = () => (settingsRef.current!.sign > 0 ? -extent() : 100 + extent());
    const exit = () => (settingsRef.current!.sign > 0 ? 100 + extent() : -extent());
    const nearest = () => (state.target < 50 ? -extent() : 100 + extent());

    const gradient = (pos: number, fill: number[]) => {
      const s = settingsRef.current!;
      const half = s.shineWidth / 2;
      const core = half * (1 - s.softness);
      const fade = half - core;
      const stops: [number, number][] = [];
      for (let band = 0; band < s.bands; band++) {
        const center = pos - s.sign * band * s.shineWidth * 1.3;
        const strength = 1 - band * 0.28;
        for (const side of [-1, 1]) {
          for (const f of FALLOFF) {
            const at = center + side * (core + fade * (1 - f));
            const amount = f * f * (3 - 2 * f) * strength;
            stops.push([at, amount]);
          }
        }
      }
      stops.sort((a, b) => a[0] - b[0]);
      const list = stops.map(([at, amount]) => `${blend(fill, shine!, amount)} ${at.toFixed(2)}%`);
      return `linear-gradient(${s.angle}deg, ${blend(fill, shine!, 0)} 0%, ${list.join(', ')}, ${blend(fill, shine!, 0)} 100%)`;
    };

    const draw = () => {
      const s = settingsRef.current!;
      const key = `${s.color}|${s.shineColor}`;
      if (key !== state.colors) {
        state.colors = key;
        base = parseColor(s.color);
        shine = parseColor(s.shineColor);
        clear = shine ? [shine[0], shine[1], shine[2], 0] : null;
      }
      if (!base || !shine) {
        root.style.backgroundImage = `linear-gradient(${s.color}, ${s.color})`;
        return;
      }
      if (state.pos === null || s.disabled) {
        root.style.backgroundImage = `linear-gradient(${s.color}, ${s.color})`;
        if (glowRef.current) glowRef.current.style.backgroundImage = 'none';
        return;
      }
      root.style.backgroundImage = gradient(state.pos, base!);
      if (glowRef.current) {
        glowRef.current.style.backgroundImage = gradient(state.pos, clear!);
        glowRef.current.style.opacity = String(s.glow);
      }
    };

    const sweep = (from: number, to: number, now: number) => {
      const s = settingsRef.current!;
      const span = Math.abs(exit() - entry()) || 1;
      state.phase = 'sweep';
      state.from = from;
      state.to = to;
      state.start = now;
      state.duration = s.speed * 1000 * Math.max(0.15, Math.abs(to - from) / span);
    };

    const wake = () => {
      if (raf || !alive) return;
      window.clearTimeout(timer);
      timer = 0;
      last = performance.now();
      raf = requestAnimationFrame(tick);
    };

    const tick = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = settingsRef.current!;
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      if (s.disabled) {
        state.pos = null;
        state.phase = 'idle';
        draw();
        return;
      }
      const following = s.followPointer && state.inside;
      if (following) {
        if (state.pos === null) state.pos = nearest();
        const stiffness = 220;
        state.vel += ((state.target - state.pos) * stiffness - state.vel * 2 * Math.sqrt(stiffness)) * dt;
        state.pos += state.vel * dt;
        state.phase = 'follow';
        draw();
        raf = requestAnimationFrame(tick);
        return;
      }
      if (state.phase === 'follow') {
        state.vel = 0;
        sweep(state.pos ?? nearest(), nearest(), now);
      }
      if (state.phase === 'sweep') {
        if (s.pauseOnHover && state.inside) {
          state.start += dt * 1000;
          raf = requestAnimationFrame(tick);
          return;
        }
        const t = clamp((now - state.start) / state.duration, 0, 1);
        state.pos = state.from + (state.to - state.from) * s.ease(t);
        draw();
        if (t < 1) {
          raf = requestAnimationFrame(tick);
          return;
        }
        if (s.trigger !== 'loop' || reduce) {
          state.phase = 'idle';
          state.pos = null;
          draw();
          return;
        }
        state.phase = 'wait';
        state.resume = now + s.delay * 1000;
      }
      if (state.phase === 'wait') {
        if (!state.visible) return;
        if (now < state.resume) {
          window.clearTimeout(timer);
          timer = window.setTimeout(wake, state.resume - now);
          return;
        }
        if (s.yoyo) {
          state.flip = !state.flip;
          sweep(state.flip ? exit() : entry(), state.flip ? entry() : exit(), now);
        } else {
          sweep(entry(), exit(), now);
        }
        raf = requestAnimationFrame(tick);
        return;
      }
      if (state.phase === 'idle' && s.trigger === 'loop' && !reduce && state.visible) {
        state.flip = false;
        sweep(entry(), exit(), now);
        raf = requestAnimationFrame(tick);
      }
    };

    const locate = (event: PointerEvent) => {
      const s = settingsRef.current!;
      const rect = root.getBoundingClientRect();
      const radians = (s.angle * Math.PI) / 180;
      const dx = Math.sin(radians);
      const dy = -Math.cos(radians);
      const length = Math.abs(rect.width * dx) + Math.abs(rect.height * dy) || 1;
      const along =
        (event.clientX - rect.left - rect.width / 2) * dx + (event.clientY - rect.top - rect.height / 2) * dy;
      return 50 + (along / length) * 100;
    };

    const onEnter = (event: PointerEvent) => {
      const s = settingsRef.current!;
      state.inside = true;
      state.target = locate(event);
      if (s.disabled) return;
      if (s.followPointer) {
        if (state.pos === null) state.pos = nearest();
      } else if (s.trigger === 'hover' && state.phase === 'idle' && !reduce) {
        sweep(entry(), exit(), performance.now());
      }
      wake();
    };
    const onMove = (event: PointerEvent) => {
      state.target = locate(event);
      if (settingsRef.current!.followPointer) wake();
    };
    const onLeave = () => {
      state.inside = false;
      wake();
    };

    const observer = new IntersectionObserver(entries => {
      const visible = entries.some(item => item.isIntersecting);
      state.visible = visible;
      const s = settingsRef.current!;
      if (!visible) return;
      if (s.trigger === 'view' && !state.seen && !reduce && !s.disabled) {
        state.seen = true;
        sweep(entry(), exit(), performance.now());
      }
      wake();
    });
    observer.observe(root);

    root.addEventListener('pointerenter', onEnter);
    root.addEventListener('pointermove', onMove);
    root.addEventListener('pointerleave', onLeave);

    syncRef.current = () => {
      const s = settingsRef.current!;
      if (s.disabled) {
        state.pos = null;
        state.phase = 'idle';
      } else if (s.trigger !== 'loop' && state.phase === 'wait') {
        state.phase = 'idle';
        state.pos = null;
      }
      draw();
      wake();
    };
    draw();
    wake();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      window.clearTimeout(timer);
      observer.disconnect();
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointermove', onMove);
      root.removeEventListener('pointerleave', onLeave);
      syncRef.current = null;
    };
  }, []);

  return (
    <span
      ref={rootRef}
      className={`relative inline-block bg-no-repeat [background-size:100%_100%] bg-clip-text [-webkit-background-clip:text] [-webkit-text-fill-color:transparent] ${className}`}
      style={{ backgroundImage: `linear-gradient(${color}, ${color})`, ...style }}
    >
      {content}
      {glow > 0 ? (
        <span
          ref={glowRef}
          className="absolute inset-0 bg-no-repeat [background-size:100%_100%] bg-clip-text [-webkit-background-clip:text] [filter:blur(0.14em)] pointer-events-none select-none"
          aria-hidden="true"
        >
          {content}
        </span>
      ) : null}
    </span>
  );
};

export default ShinyText;

'use client';

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { SplitText as GSAPSplitText } from 'gsap/SplitText';
import { useGSAP } from '@gsap/react';

gsap.registerPlugin(ScrollTrigger, GSAPSplitText, useGSAP);

const FONT_WEIGHTS = new Set([
  'thin',
  'extralight',
  'light',
  'normal',
  'medium',
  'semibold',
  'bold',
  'extrabold',
  'black'
]);

const hasFontFamilyClass = (className: string) =>
  className.split(/\s+/).some(name => {
    const utility = name.split(':').pop() ?? '';
    return utility.startsWith('font-') && !FONT_WEIGHTS.has(utility.slice(5));
  });

export interface ShuffleProps {
  text: string;
  className?: string;
  style?: React.CSSProperties;
  shuffleDirection?: 'left' | 'right' | 'up' | 'down';
  duration?: number;
  maxDelay?: number;
  ease?: string | ((t: number) => number);
  threshold?: number;
  rootMargin?: string;
  tag?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6' | 'p' | 'span';
  textAlign?: React.CSSProperties['textAlign'];
  onShuffleComplete?: () => void;
  shuffleTimes?: number;
  animationMode?: 'evenodd' | 'sequence' | 'center' | 'random';
  loop?: boolean;
  loopDelay?: number;
  stagger?: number;
  scrambleCharset?: string;
  colorFrom?: string;
  colorTo?: string;
  triggerOnce?: boolean;
  respectReducedMotion?: boolean;
  triggerOnHover?: boolean;
  effect?: 'slide' | 'flip' | 'blur';
  hoverRadius?: number;
  motionBlur?: boolean;
  color?: string;
  accentColor?: string;
}

interface ShuffleCell {
  wrap: HTMLSpanElement;
  inner: HTMLSpanElement;
  orig: HTMLElement;
  text: string;
  w: number;
  h: number;
  size: number;
  mids: HTMLElement[];
  seq: string[];
  shown: number;
  from: number;
  to: number;
  speed: number;
  lastValue: number;
  lastTime: number;
  blurLevel: number;
  busy: boolean;
  near: boolean;
  travel: number;
}

const SVG_NS = 'http://www.w3.org/2000/svg';
const BLUR_STEPS = 12;

const Shuffle: React.FC<ShuffleProps> = ({
  text,
  className = '',
  style = {},
  shuffleDirection = 'right',
  duration = 0.35,
  maxDelay = 0,
  ease = 'power3.out',
  threshold = 0.1,
  rootMargin = '-100px',
  tag = 'p',
  textAlign = 'center',
  onShuffleComplete,
  shuffleTimes = 1,
  animationMode = 'evenodd',
  loop = false,
  loopDelay = 0,
  stagger = 0.03,
  scrambleCharset = '',
  colorFrom,
  colorTo,
  triggerOnce = true,
  respectReducedMotion = true,
  triggerOnHover = true,
  effect = 'slide',
  hoverRadius = 0,
  motionBlur = false,
  color,
  accentColor
}) => {
  const ref = useRef<HTMLElement>(null);
  const [fontsLoaded, setFontsLoaded] = useState(false);
  const [ready, setReady] = useState(false);

  const splitRef = useRef<GSAPSplitText | null>(null);
  const tlRef = useRef<gsap.core.Timeline | null>(null);
  const playingRef = useRef(false);
  const onCompleteRef = useRef(onShuffleComplete);

  useEffect(() => {
    onCompleteRef.current = onShuffleComplete;
  }, [onShuffleComplete]);

  useEffect(() => {
    if ('fonts' in document) {
      if (document.fonts.status === 'loaded') setFontsLoaded(true);
      else document.fonts.ready.then(() => setFontsLoaded(true));
    } else setFontsLoaded(true);
  }, []);

  const scrollTriggerStart = useMemo(() => {
    const startPct = (1 - threshold) * 100;
    const mm = /^(-?\d+(?:\.\d+)?)(px|em|rem|%)?$/.exec(rootMargin || '');
    const mv = mm ? parseFloat(mm[1]) : 0;
    const mu = mm ? mm[2] || 'px' : 'px';
    const sign = mv === 0 ? '' : mv < 0 ? `-=${Math.abs(mv)}${mu}` : `+=${mv}${mu}`;
    return `top ${startPct}%${sign}`;
  }, [threshold, rootMargin]);

  useGSAP(
    () => {
      if (!ref.current || !text || !fontsLoaded) return;
      if (respectReducedMotion && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        setReady(true);
        onCompleteRef.current?.();
        return;
      }

      const el = ref.current as HTMLElement;
      const mode = effect === 'flip' || effect === 'blur' ? effect : 'slide';
      const isVertical = shuffleDirection === 'up' || shuffleDirection === 'down';
      const axis = isVertical ? 'y' : 'x';
      const forward = shuffleDirection === 'right' || shuffleDirection === 'down';
      const rolls = Math.max(1, Math.floor(shuffleTimes));
      const blurred = mode === 'blur' || (mode === 'slide' && motionBlur);
      const local = triggerOnHover && hoverRadius > 0;
      const uid = Math.random().toString(36).slice(2, 9);
      const running = new Set<gsap.core.Timeline>();
      const pointer = { x: 0, y: 0, lastX: 0, lastY: 0, seen: false };
      let cells: ShuffleCell[] = [];
      let baseColor = '';
      let svg: SVGSVGElement | null = null;
      let blurMax = 0;
      let moveFrame = 0;
      let unhover: (() => void) | null = null;

      const pick = (fallback: string) =>
        scrambleCharset ? scrambleCharset.charAt(Math.floor(Math.random() * scrambleCharset.length)) : fallback;

      const ensureFilters = (unit: number) => {
        if (svg || !blurred) return;
        blurMax = Math.max(2, unit * (mode === 'blur' ? 0.26 : 0.24));
        svg = document.createElementNS(SVG_NS, 'svg');
        svg.setAttribute('aria-hidden', 'true');
        svg.setAttribute('width', '0');
        svg.setAttribute('height', '0');
        Object.assign(svg.style, { position: 'absolute', width: '0', height: '0', overflow: 'hidden' });
        for (let k = 1; k <= BLUR_STEPS; k++) {
          const filter = document.createElementNS(SVG_NS, 'filter');
          filter.setAttribute('id', `shuffle-${uid}-${k}`);
          filter.setAttribute('x', isVertical ? '-10%' : '-100%');
          filter.setAttribute('y', isVertical ? '-100%' : '-10%');
          filter.setAttribute('width', isVertical ? '120%' : '300%');
          filter.setAttribute('height', isVertical ? '300%' : '120%');
          filter.setAttribute('color-interpolation-filters', 'sRGB');
          const blur = document.createElementNS(SVG_NS, 'feGaussianBlur');
          const amount = (blurMax * Math.pow(k / BLUR_STEPS, 1.5)).toFixed(2);
          blur.setAttribute('stdDeviation', isVertical ? `0 ${amount}` : `${amount} 0`);
          filter.appendChild(blur);
          svg.appendChild(filter);
        }
        document.body.appendChild(svg);
      };

      const setBlur = (cell: ShuffleCell, amount: number) => {
        if (!svg) return;
        const level = Math.round(BLUR_STEPS * Math.pow(Math.min(1, Math.max(0, amount) / blurMax), 1 / 1.5));
        if (level === cell.blurLevel) return;
        cell.blurLevel = level;
        const node = mode === 'slide' ? cell.inner : cell.orig;
        node.style.filter = level ? `url(#shuffle-${uid}-${level})` : '';
      };

      const trackSpeed = (cell: ShuffleCell, value: number) => {
        const now = gsap.ticker.time;
        const dt = now - cell.lastTime;
        if (dt > 0) cell.speed = cell.speed * 0.35 + (Math.abs(value - cell.lastValue) / dt) * 0.65;
        cell.lastValue = value;
        cell.lastTime = now;
        return cell.speed;
      };

      const teardown = () => {
        if (tlRef.current) {
          tlRef.current.kill();
          tlRef.current = null;
        }
        running.forEach(tl => tl.kill());
        running.clear();
        cells.forEach(cell => {
          if (cell.wrap.parentNode) cell.wrap.parentNode.replaceChild(cell.orig, cell.wrap);
        });
        cells = [];
        try {
          splitRef.current?.revert();
        } catch {}
        splitRef.current = null;
        playingRef.current = false;
      };

      const build = () => {
        teardown();

        splitRef.current = new GSAPSplitText(el, {
          type: 'chars',
          charsClass: 'shuffle-char',
          wordsClass: 'shuffle-word',
          linesClass: 'shuffle-line',
          smartWrap: true,
          reduceWhiteSpace: false
        });

        const chars = (splitRef.current.chars || []) as HTMLElement[];
        const strip = mode === 'slide';
        const metricsContext = strip && isVertical ? document.createElement('canvas').getContext('2d') : null;
        baseColor = window.getComputedStyle(el).color;

        const measureVerticalCell = (node: HTMLElement, lineBoxHeight: number) => {
          const computed = window.getComputedStyle(node);
          let fontHeight = 0;

          if (metricsContext) {
            metricsContext.font = [
              computed.fontStyle,
              computed.fontVariant,
              computed.fontWeight,
              computed.fontSize,
              computed.fontFamily
            ].join(' ');

            const sample = `${node.textContent || 'M'}${scrambleCharset}`;
            const metrics = metricsContext.measureText(sample);
            const ascent = metrics.fontBoundingBoxAscent;
            const descent = metrics.fontBoundingBoxDescent;
            if (Number.isFinite(ascent) && Number.isFinite(descent)) fontHeight = ascent + descent;
          }

          if (!fontHeight) {
            const probe = node.cloneNode(true) as HTMLElement;
            probe.textContent = `${node.textContent || 'M'}${scrambleCharset}`;
            Object.assign(probe.style, {
              position: 'absolute',
              visibility: 'hidden',
              pointerEvents: 'none',
              width: 'auto',
              height: 'auto',
              whiteSpace: 'nowrap',
              lineHeight: 'normal',
              fontFamily: computed.fontFamily,
              fontSize: computed.fontSize,
              fontStyle: computed.fontStyle,
              fontVariant: computed.fontVariant,
              fontWeight: computed.fontWeight,
              fontStretch: computed.fontStretch
            });
            document.body.appendChild(probe);
            fontHeight = probe.getBoundingClientRect().height;
            probe.remove();
          }

          const overflow = Math.max(0, Math.ceil(fontHeight - lineBoxHeight));
          const padTop = Math.floor(overflow / 2);
          return { cellHeight: lineBoxHeight + overflow, padTop, padBottom: overflow - padTop };
        };

        chars.forEach(ch => {
          const parent = ch.parentElement;
          if (!parent) return;

          const w = ch.getBoundingClientRect().width;
          const h = ch.getBoundingClientRect().height;
          if (!w) return;

          const { cellHeight, padTop, padBottom } = metricsContext
            ? measureVerticalCell(ch, h)
            : { cellHeight: h, padTop: 0, padBottom: 0 };
          const tall = strip && isVertical;

          const wrap = document.createElement('span');
          Object.assign(wrap.style, {
            display: 'inline-block',
            overflow: strip ? 'hidden' : 'visible',
            width: w + 'px',
            height: tall ? cellHeight + 'px' : 'auto',
            marginTop: tall ? -padTop + 'px' : '0',
            marginBottom: tall ? -padBottom + 'px' : '0',
            verticalAlign: 'bottom',
            perspective: mode === 'flip' ? Math.round(h * 3.2) + 'px' : ''
          });

          const inner = document.createElement('span');
          Object.assign(inner.style, {
            display: 'inline-block',
            whiteSpace: isVertical ? 'normal' : 'nowrap',
            willChange: mode === 'slide' ? 'transform' : 'transform, opacity'
          });

          parent.insertBefore(wrap, ch);
          wrap.appendChild(inner);

          Object.assign(ch.style, {
            display: tall ? 'flex' : 'inline-block',
            alignItems: tall ? 'center' : '',
            justifyContent: tall ? 'center' : '',
            height: tall ? cellHeight + 'px' : '',
            lineHeight: tall ? h + 'px' : '',
            width: w + 'px',
            textAlign: 'center'
          });
          inner.appendChild(ch);

          if (colorFrom) wrap.style.color = colorFrom;
          cells.push({
            wrap,
            inner,
            orig: ch,
            text: ch.textContent || '',
            w,
            h,
            size: isVertical ? cellHeight : w,
            mids: [],
            seq: [],
            shown: -1,
            from: 0,
            to: 0,
            speed: 0,
            lastValue: 0,
            lastTime: 0,
            blurLevel: 0,
            busy: false,
            near: false,
            travel: 0
          });
        });

        if (cells.length) ensureFilters(isVertical ? cells[0].size : cells[0].h);
      };

      const fillStrip = (cell: ShuffleCell, count: number) => {
        const head = cell.orig.cloneNode(true) as HTMLElement;
        const mids: HTMLElement[] = [];
        for (let k = 0; k < count; k++) {
          const node = cell.orig.cloneNode(true) as HTMLElement;
          node.textContent = pick(cell.text);
          if (accentColor) node.style.color = accentColor;
          mids.push(node);
        }
        cell.mids = mids;
        cell.inner.replaceChildren(...(forward ? [cell.orig, ...mids, head] : [head, ...mids, cell.orig]));
        const span = (count + 1) * cell.size;
        cell.from = forward ? -span : 0;
        cell.to = forward ? 0 : -span;
        gsap.set(cell.inner, { x: 0, y: 0, [axis]: cell.from, force3D: true });
      };

      const fillSequence = (cell: ShuffleCell, count: number) => {
        cell.seq = [cell.text];
        for (let k = 0; k < count; k++) cell.seq.push(pick(cell.text));
        cell.seq.push(cell.text);
        cell.shown = -1;
      };

      const reroll = (cell: ShuffleCell) => {
        if (mode === 'slide') cell.mids.forEach(node => (node.textContent = pick(cell.text)));
        else for (let k = 1; k < cell.seq.length - 1; k++) cell.seq[k] = pick(cell.text);
      };

      const showGlyph = (cell: ShuffleCell, index: number) => {
        if (cell.shown === index) return;
        cell.shown = index;
        cell.orig.textContent = cell.seq[index];
        cell.orig.style.color = accentColor && index > 0 && index < cell.seq.length - 1 ? accentColor : '';
      };

      const renderFlip = (cell: ShuffleCell, t: number) => {
        const last = cell.seq.length - 1;
        const nearest = Math.round(t);
        showGlyph(cell, Math.max(0, Math.min(last, nearest)));
        const angle = (t - nearest) * 180;
        const facing = Math.abs(Math.cos((angle * Math.PI) / 180));
        const turn = isVertical ? (forward ? -angle : angle) : forward ? angle : -angle;
        gsap.set(cell.inner, {
          [isVertical ? 'rotationX' : 'rotationY']: turn,
          z: Math.sin(Math.PI * Math.min(1, Math.max(0, t / last))) * cell.h * 0.22,
          opacity: 0.22 + 0.78 * Math.pow(facing, 1.5)
        });
      };

      const renderBlur = (cell: ShuffleCell, t: number) => {
        const last = cell.seq.length - 1;
        const nearest = Math.round(t);
        const phase = Math.max(-0.5, Math.min(0.5, t - nearest));
        showGlyph(cell, Math.max(0, Math.min(last, nearest)));
        const speed = trackSpeed(cell, t);
        gsap.set(cell.inner, {
          [axis]: (forward ? 1 : -1) * phase * cell.size * 0.42,
          opacity: 0.5 + 0.5 * Math.pow(Math.cos(phase * Math.PI), 0.7)
        });
        setBlur(cell, speed * cell.size * 0.012);
      };

      const animateCell = (cell: ShuffleCell, count: number, dur: number) => {
        const tl = gsap.timeline();
        if (mode === 'slide') {
          fillStrip(cell, count);
          tl.fromTo(
            cell.inner,
            { [axis]: cell.from },
            {
              [axis]: cell.to,
              duration: dur,
              ease,
              force3D: true,
              immediateRender: false,
              onStart: () => {
                cell.speed = 0;
                cell.lastValue = cell.from;
                cell.lastTime = gsap.ticker.time;
              },
              onUpdate: blurred
                ? () => setBlur(cell, trackSpeed(cell, Number(gsap.getProperty(cell.inner, axis))) * 0.0065)
                : undefined,
              onComplete: () => setBlur(cell, 0)
            },
            0
          );
        } else {
          fillSequence(cell, count);
          const proxy = { t: 0 };
          const render = mode === 'flip' ? renderFlip : renderBlur;
          tl.fromTo(
            proxy,
            { t: 0 },
            {
              t: count + 1,
              duration: dur,
              ease,
              immediateRender: false,
              onStart: () => {
                cell.speed = 0;
                cell.lastValue = 0;
                cell.lastTime = gsap.ticker.time;
              },
              onUpdate: () => render(cell, proxy.t),
              onComplete: () => setBlur(cell, 0)
            },
            0
          );
        }
        if (colorFrom || colorTo) {
          tl.fromTo(
            cell.wrap,
            { color: colorFrom || baseColor },
            { color: colorTo || baseColor, duration: dur, ease, immediateRender: false },
            0
          );
        }
        return tl;
      };

      const settle = (cell: ShuffleCell) => {
        if (mode === 'slide') {
          cell.inner.replaceChildren(cell.orig);
          cell.mids = [];
        } else {
          cell.orig.textContent = cell.text;
          cell.orig.style.color = '';
          cell.shown = -1;
        }
        gsap.set(cell.inner, { clearProps: 'transform,opacity' });
        setBlur(cell, 0);
        cell.wrap.style.color = colorTo || '';
      };

      const startOffsets = (): number[] => {
        if (animationMode === 'evenodd') {
          const oddCount = Math.floor(cells.length / 2);
          const evenStart = oddCount ? (duration + Math.max(0, oddCount - 1) * stagger) * 0.7 : 0;
          return cells.map((_, i) => (i % 2 === 1 ? Math.floor(i / 2) * stagger : evenStart + (i / 2) * stagger));
        }
        if (animationMode === 'center') {
          const spread = gsap.utils.distribute({ each: stagger, from: 'center' });
          return cells.map((cell, i) => spread(i, cell, cells));
        }
        if (animationMode === 'sequence') return cells.map((_, i) => i * stagger);
        return cells.map(() => Math.random() * maxDelay);
      };

      const play = () => {
        if (!cells.length) return;
        playingRef.current = true;
        const offsets = startOffsets();

        const tl = gsap.timeline({
          repeat: loop ? -1 : 0,
          repeatDelay: loop ? loopDelay : 0,
          onRepeat: () => {
            cells.forEach(reroll);
            onCompleteRef.current?.();
          },
          onComplete: () => {
            playingRef.current = false;
            if (loop) return;
            cells.forEach(settle);
            onCompleteRef.current?.();
            armHover();
          }
        });

        cells.forEach((cell, i) => tl.add(animateCell(cell, rolls, duration), offsets[i]));
        tlRef.current = tl;
      };

      const shuffleNear = (cell: ShuffleCell, strength: number) => {
        cell.busy = true;
        const tl = animateCell(
          cell,
          Math.max(1, Math.round(rolls * (0.35 + 0.65 * strength))),
          duration * (0.5 + 0.5 * strength)
        );
        tl.delay((1 - strength) * 0.08);
        tl.eventCallback('onComplete', () => {
          running.delete(tl);
          cell.busy = false;
          settle(cell);
        });
        running.add(tl);
      };

      const scan = () => {
        moveFrame = 0;
        if (playingRef.current || !cells.length) return;
        const moved = pointer.seen ? Math.hypot(pointer.x - pointer.lastX, pointer.y - pointer.lastY) : 0;
        pointer.lastX = pointer.x;
        pointer.lastY = pointer.y;
        pointer.seen = true;
        const box = el.getBoundingClientRect();
        const outside =
          pointer.x < box.left - hoverRadius ||
          pointer.x > box.right + hoverRadius ||
          pointer.y < box.top - hoverRadius ||
          pointer.y > box.bottom + hoverRadius;

        cells.forEach(cell => {
          let distance = Infinity;
          if (!outside) {
            const rect = cell.wrap.getBoundingClientRect();
            distance = Math.hypot(pointer.x - (rect.left + rect.width / 2), pointer.y - (rect.top + rect.height / 2));
          }
          if (distance >= hoverRadius) {
            cell.near = false;
            cell.travel = 0;
            return;
          }
          const reach = 1 - distance / hoverRadius;
          const strength = reach * reach * (3 - 2 * reach);
          const entered = !cell.near;
          cell.near = true;
          cell.travel += moved * (0.35 + strength);
          if (cell.busy || (!entered && cell.travel < cell.w * 1.4)) return;
          cell.travel = 0;
          shuffleNear(cell, strength);
        });
      };

      const handlePointerMove = (event: PointerEvent) => {
        pointer.x = event.clientX;
        pointer.y = event.clientY;
        if (!moveFrame) moveFrame = requestAnimationFrame(scan);
      };

      const removeHover = () => {
        unhover?.();
        unhover = null;
      };

      const armHover = () => {
        if (!triggerOnHover) return;
        removeHover();
        if (local) {
          window.addEventListener('pointermove', handlePointerMove, { passive: true });
          unhover = () => {
            window.removeEventListener('pointermove', handlePointerMove);
            cancelAnimationFrame(moveFrame);
            moveFrame = 0;
          };
          return;
        }
        const handleEnter = () => {
          if (playingRef.current) return;
          build();
          play();
        };
        el.addEventListener('mouseenter', handleEnter);
        unhover = () => el.removeEventListener('mouseenter', handleEnter);
      };

      const create = () => {
        build();
        play();
        armHover();
        setReady(true);
      };

      const st = ScrollTrigger.create({
        trigger: el,
        start: scrollTriggerStart,
        once: triggerOnce,
        onEnter: create
      });

      return () => {
        st.kill();
        removeHover();
        teardown();
        svg?.remove();
        svg = null;
        setReady(false);
      };
    },
    {
      dependencies: [
        text,
        duration,
        maxDelay,
        ease,
        scrollTriggerStart,
        fontsLoaded,
        shuffleDirection,
        shuffleTimes,
        animationMode,
        loop,
        loopDelay,
        stagger,
        scrambleCharset,
        colorFrom,
        colorTo,
        triggerOnce,
        respectReducedMotion,
        triggerOnHover,
        effect,
        hoverRadius,
        motionBlur,
        color,
        accentColor
      ],
      scope: ref
    }
  );

  const userHasFont = hasFontFamilyClass(className);

  const commonStyle: React.CSSProperties = useMemo(
    () => ({
      textAlign,
      ...(userHasFont ? {} : { fontFamily: "'Press Start 2P', sans-serif" }),
      ...(color ? { color } : {}),
      ...style
    }),
    [textAlign, userHasFont, color, style]
  );

  const classes = `inline-block whitespace-normal break-words will-change-transform uppercase text-[4rem] leading-none ${ready ? 'visible' : 'invisible'} ${className}`;

  const Tag = (tag || 'p') as React.ElementType;
  return React.createElement(Tag, { ref, className: classes, style: commonStyle }, text);
};

